/* Baza pytań modułowych Neurologia V – Hub (70 pytań z 10 atlasów z omówieniami) */
window.HUB_MODULOWA_Q = [{"id":"nagle-q1","at":"nagle","type":"mcq","mods":["3"],"topic":"Świadomość i skale","stem":"Pacjent po ostrym incydencie naczyniowym w obrębie pnia mózgu leży z porażeniem czterokończynowym, nie mówi i nie wykonuje ruchów mimicznych, ale zachowuje pełną świadomość i odpowiada na pytania poprzez pionowe ruchy gałek ocznych oraz mruganie. Wskaż najbardziej prawdopodobną lokalizację uszkodzenia oraz skalę dokładniejszą od GCS w tym stanie:","opts":["Brzuszna część mostu (zespół zamknięcia, locked-in syndrome); skala FOUR","Obustronne uszkodzenie kory przedczołowej; skala NIHSS","Rozlane uszkodzenie tworu siatkowatego śródmózgowia (ARAS); skala GCS","Obustronne uszkodzenie móżdżku; skala Fishera","Izolowane uszkodzenie nerwu błędnego (X); skala Hunt-Hessa"],"keys":[0],"conf":"src","adapt":false,"gap":false,"src":"Sylabus PUM · TK02 / Podemski","why":"Zespół zamknięcia (locked-in) wynika najczęściej z zawału brzusznej części mostu (niedrożność tętnicy podstawnej) uszkadzającego drogi korowo-rdzeniowe i korowo-jądrowe przy zaoszczędzeniu nakrywki pnia i układu ARAS. Zachowana jest pełna świadomość oraz pionowe ruchy gałek ocznych i mruganie. Skala FOUR aktywnie testuje mruganie i pionowe ruchy oczu, dzięki czemu nie zaniża stanu chorego jak klasyczna skala GCS.","tip":"Zawsze weryfikuj pionowe ruchy oczu i mruganie u pozornie nieprzytomnego pacjenta – pozwala to odróżnić zespół zamknięcia od śpiączki i stanu wegetatywnego.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"nagle-q2","at":"nagle","type":"mcq","mods":["1"],"topic":"ICP i wgłobienia","stem":"U 62-letniego chorego z guzem prawej półkuli mózgu doszło do gwałtownego pogorszenia świadomości, poszerzenia i braku reakcji na światło prawej źrenicy (anizokorii), narastającego nadciśnienia tętniczego (200/110 mmHg), bradykardii (42/min) i nieregularnego oddechu. Który zespół kliniczny rozpoznajesz?","opts":["Wgłobienie pod sierp mózgu z uciskiem tętnicy przedniej mózgu","Wgłobienie haka zakrętu przyhipokampowego z uciskiem prawego nerwu III i zagrażającym wgłobieniem pnia (triada Cushinga)","Zespół Hornera po stronie lewej w przebiegu rozwarstwienia tętnicy szyjnej","Izolowane porażenie nerwu odwodzącego (n. VI) bez zagrożenia pnia mózgu"],"keys":[1],"conf":"src","adapt":false,"gap":false,"src":"Sylabus PUM · TK01, U05 / Fuller","why":"Jednostronne rozszerzenie źrenicy po stronie zmiany wynika z ucisku powierzchownych włókien przywspółczulnych nerwu okoruchowego (n. III) przez przemieszczający się hak zakrętu przyhipokampowego (wgłobienie podnamiotowe / wcięcia namiotu). Współistnienie nadciśnienia tętniczego, bradykardii i zaburzeń oddechu tworzy triadę Cushinga – późny alarm zagrażającego wgłobienia pnia mózgu.","tip":"Porażenie n. III (szeroka, sztywna źrenica) jest zazwyczaj tożstronne do krwiaka/guza, natomiast przeciwległy niedowład bywa czasem tożstronny w mechanizmie wcięcia Kernohana.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"nagle-q3","at":"nagle","type":"mcq","mods":["1"],"topic":"ICP i wgłobienia","stem":"Mężczyzna po ciężkim urazie czaszkowo-mózgowym (GCS 6 pkt) ma objawy narastającego wzmożonego ciśnienia śródczaszkowego (ICP 28 mmHg). Który zestaw działań w ramach wstępnej stabilizacji jest PRAWIDŁOWY?","opts":["Natychmiastowe podanie wysokich dawek deksametazonu i.v. w celu zmniejszenia obrzęku pourazowego","Ułożenie w pozycji Trendelenburga i przewlekła hiperwentylacja do PaCO₂ < 25 mmHg przez 24 godziny","Uniesienie wezgłowia łóżka o 30° w osi pośrodkowej, intubacja z utrzymaniem normokapni (PaCO₂ 35–40 mmHg) oraz terapia hiperosmolarna (mannitol lub hipertoniczny NaCl)","Szybki wlew dożylny 5% roztworu glukozy jako płynu hipotonicznego","Natychmiastowe nakłucie lędźwiowe w celu odbarczenia przestrzeni płynowych"],"keys":[2],"conf":"inf","adapt":false,"gap":true,"src":"Wytyczne Brain Trauma Foundation / Sylabus U05","why":"Redukcję ICP rozpoczyna się od uniesienia wezgłowia o 30° w linii pośrodkowej (usprawnienie odpływu żylnego), zabezpieczenia dróg oddechowych przy GCS ≤ 8 z utrzymaniem normokapni (krótkotrwała hiperwentylacja 30–35 mmHg tylko doraźnie przy aktywnym wgłobieniu) oraz podania mannitolu 20% lub hipertonicznego NaCl. Płyny hipotoniczne i punkcja lędźwiowa są przeciwwskazane.","tip":"Zapamiętaj rozróżnienie steroidów: deksametazon działa na obrzęk naczyniopochodny (guz, ropień), NIE na uraz mózgu ani udar.","zal":"W starszych materiałach glikokortykosteroidy bywały wymieniane ogólnie jako leki przeciwobrzękowe w OUN.","akt":"Wg wytycznych Brain Trauma Foundation oraz badania CRASH steroidy są przeciwwskazane w urazie czaszkowo-mózgowym (zwiększają śmiertelność); stosuje się wyłącznie terapię hiperosmolarną (mannitol, HTS).","ans":"","reps":0,"bank":"modulowa"},{"id":"nagle-q4","at":"nagle","type":"mcq","mods":["1"],"topic":"Neuroinfekcje (ZOMR)","stem":"58-letni chory został przyjęty na SOR z gorączką 39,2°C, silnym bólem głowy, sztywnością karku, zaburzeniami świadomości (GCS 11 pkt) i świeżym niedowładem prawostronnym. Który schemat postępowania jest PRAWIDŁOWY?","opts":["Natychmiastowa punkcja lędźwiowa bez badania obrazowego, a włączenie antybiotyku dopiero po wyniku preparatu bezpośredniego PMR","Pobranie posiewów krwi, natychmiastowe podanie deksametazonu i antybiotykoterapii empirycznej i.v. (ceftriakson + wankomycyna + ampicylina), a następnie wykonanie TK głowy przed ewentualną punkcją lędźwiową","Wykonanie TK głowy i odczekanie z wdrożeniem antybiotyku aż do uzyskania pełnej analizy PMR po punkcji","Zastosowanie wyłącznie acyklowiru i obserwacja przez 12 godzin bez antybiotyku"],"keys":[1],"conf":"inf","adapt":false,"gap":true,"src":"Wytyczne ESCMID / IDSA · Sylabus U06","why":"Zaburzenia świadomości (GCS < 12) oraz objawy ogniskowe (niedowład) stanowią wskazanie do TK głowy przed punkcją lędźwiową w celu wykluczenia efektu masy i ryzyka wgłobienia. Nie wolno jednak opóźniać leczenia: przed transportem na TK pobiera się posiewy krwi i natychmiast podaje deksametazon oraz antybiotyki empiryczne (u chorych > 50 r.ż. zawsze z ampicyliną przeciwko Listeria monocytogenes).","tip":"Złota reguła SOR przy podejrzeniu ropnego ZOMR: posiew krwi + deksametazon + antybiotyk PRZED TK głowy.","zal":"W części schematów podręcznikowych kolejność opisywano jako „punkcja lędźwiowa w celu rozpoznania → antybiotykoterapia”.","akt":"Aktualne wytyczne ESCMID/IDSA nakazują natychmiastowe podanie deksametazonu i antybiotyku i.v. przed wykonaniem TK głowy i LP u każdego pacjenta ze wskazaniami do neuroobrazowania przed punkcją.","ans":"","reps":0,"bank":"modulowa"},{"id":"nagle-q5","at":"nagle","type":"mcq","mods":["1"],"topic":"Neuroinfekcje (ZOMR)","stem":"U pacjenta z gorączką, bólami głowy, zaburzeniami zachowania i napadem padaczkowym wykonano nakłucie lędźwiowe: płyn wodojasny, cytoza 135 komórek/µl (90% limfocyty), białko 76 mg/dl, stężenie glukozy w PMR prawidłowe (65% glikemii). Jakie rozpoznanie i natychmiastowe leczenie jest najbardziej wskazane?","opts":["Bakteryjne ropne ZOMR — włączenie wyłącznie cefazoliny","Gruźlicze ZOMR — typowo prawidłowa glukoza i neutrofilia w PMR","Zespół Guillaina-Barrégo — rozszczepienie białkowo-komórkowe","Podejrzenie opryszczkowego zapalenia mózgu (HSV-1) — natychmiastowe włączenie acyklowiru i.v. (10 mg/kg co 8 h) bez czekania na wynik PCR oraz pilne MRI mózgu"],"keys":[3],"conf":"did","adapt":false,"gap":false,"src":"Sylabus PUM · U06, W03i / Kozubski","why":"Limfocytarna pleocytoza z umiarkowanie podwyższonym białkiem i prawidłowym stężeniem glukozy w PMR przemawia za infekcją wirusową, a współistnienie objawów uszkodzenia miąższu mózgu (zaburzenia zachowania, świadomości, napady padaczkowe) nakazuje natychmiastowe podejrzenie zapalenia mózgu HSV-1. Acyklowir i.v. trzeba włączyć natychmiast, nie czekając na wynik PCR ani MRI (zmiany w płatach skroniowych).","tip":"Samo wirusowe ZOMR nie daje objawów ogniskowych ani zaburzeń świadomości – ich obecność oznacza zapalenie mózgu (encephalitis) i wymusza natychmiastowy acyklowir!","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"nagle-q6","at":"nagle","type":"mcq","mods":["1"],"topic":"Urazy i zatrucia","stem":"28-letni mężczyzna po uderzeniu w okolicę skroniową na boisku stracił przytomność na 2 minuty, po czym odzyskał pełny kontakt („przejaśnienie świadomości”), a po 3 godzinach stał się gwałtownie senny i rozwinął poszerzenie lewej źrenicy. Jaki obraz w TK głowy bez kontrastu jest najbardziej typowy?","opts":["Sierpowata (wklęsło-wypukła) przestrzeń hiperdensyjna przekraczająca szwy czaszki, ale ograniczona sierpem mózgu","Dwuwypukła (soczewkowata) masa hiperdensyjna nieprzekraczająca szwów czaszki, typowa dla krwawienia z tętnicy oponowej środkowej","Symetryczne hiperdensyjne wypełnienie zbiorników podstawy mózgu i szczeliny Sylwiusza","Prawidłowy obraz TK wykluczający ostry krwiak wewnątrzczaszkowy"],"keys":[1],"conf":"src","adapt":false,"gap":false,"src":"Sylabus PUM · U07 / Podemski, Stępień","why":"Krótka utrata przytomności, okres przejaśnienia świadomości (lucid interval) i wtórne szybkie pogorszenie po urazie okolicy skroniowej to klasyczny obraz ostrego krwiaka nadtwardówkowego (EDH) z uszkodzonej tętnicy oponowej środkowej. W TK przybiera kształt dwuwypukłej soczewki i nie przekracza szwów czaszki, ponieważ opona twarda jest do nich silnie przyrośnięta.","tip":"Pamiętaj parę przeciwieństw: EDH = tętniczy, dwuwypukły, NIE przekracza szwów; SDH = żylny (żyły mostkowe), sierpowaty, PRZEKRACZA szwy.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"nagle-q7","at":"nagle","type":"mcq","mods":["3"],"topic":"Urazy i zatrucia","stem":"Do SOR przywieziono nieprzytomnego (GCS 7 pkt) 49-letniego mężczyznę z wywiadem przewlekłego alkoholizmu i wyniszczenia. Glikemia przyłóżkowa wynosi 31 mg/dl. Które postępowanie jest OBOWIĄZKOWE podczas wyrównywania hipoglikemii?","opts":["Podanie bolusowe flumazenilu przed wlewem glukozy","Wykonanie nakłucia lędźwiowego przed wyrównaniem glikemii","Podanie tiaminy (witaminy B1) i.v. przed lub równocześnie z roztworem glukozy dla zapobieżenia encefalopatii Wernickego","Zastosowanie naloksonu w pierwszej kolejności bez wlewu glukozy"],"keys":[2],"conf":"did","adapt":false,"gap":false,"src":"Sylabus PUM · TK02, U03 / Fuller","why":"U chorych niedożywionych lub uzależnionych od alkoholu zapasy witaminy B1 są wyczerpane. Dożylne podanie samej glukozy zużywa resztki tiaminy jako kofaktora przemian węglowodanowych i może wywołać ostrą encefalopatię Wernickego (zaburzenia gałkoruchowe, ataksja, ciężkie zaburzenia świadomości). Ponadto u upojonego pacjenta z GCS ≤ 8 należy zawsze wykluczyć ukryty uraz głowy i krwiak podtwardówkowy.","tip":"W stanach nagłych neurologicznych glikemię oznacza się natychmiast, a u wyniszczonego/alkoholika kolejność brzmi: najpierw lub równocześnie tiamina (B1), potem glukoza.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"udar-q1","at":"udar","type":"mcq","mods":["2"],"topic":"Tętnice mózgowe","stem":"64-letni mężczyzna doznał nagłego osłabienia głównie prawej kończyny dolnej (siła w kończynie górnej 4+/5, w dolnej 1/5), nietrzymania moczu oraz wyraźnej apatii i spowolnienia napędu (abulia). Które naczynie uległo najpewniej zamknięciu?","opts":["Lewa tętnica środkowa mózgu (MCA)","Lewa tętnica przednia mózgu (ACA)","Lewa tętnica tylna mózgu (PCA)","Tętnica podstawna (BA)","Lewa tętnica móżdżkowa dolna tylna (PICA)"],"keys":[1],"conf":"src","adapt":false,"gap":false,"src":"Sylabus PUM W03b · Wskazówka #5 · Podemski","why":"Tętnica przednia mózgu (ACA) zaopatruje przyśrodkową powierzchnię płata czołowego i ciemieniowego — reprezentację korową kończyny dolnej oraz płat czołowy przyśrodkowy (napęd, kontrola mikcji). Stąd przeciwstronny niedowład kończyny dolnej > górnej, abulia, nietrzymanie moczu i odruch chwytny.","tip":"Wskazówka PUM #5: ACA = noga > ręka + abulia; MCA = twarz i ręka > noga + afazja / zespół zaniedbywania; PCA = hemianopsja jednoimienna.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"udar-q2","at":"udar","type":"mcq","mods":["2"],"topic":"Tętnice mózgowe","stem":"59-letni chory z nagłymi zawrotami głowy, nudnościami, dysfagią, chrypką oraz ataksją lewej ręki. W badaniu stwierdzono lewostronny zespół Hornera, zniesienie czucia bólu i temperatury na lewej połowie twarzy oraz na prawych kończynach i tułowiu, przy prawidłowej sile mięśniowej wszystkich kończyn. Rozpoznanie to:","opts":["Zespół Webera (śródmózgowie)","Zespół boczny opuszki (Wallenberga) — zamknięcie PICA / tętnicy kręgowej","Zespół zamknięcia (locked-in) w zakrzepicy tętnicy podstawnej","Udar lakunarny w odnodze tylnej torebki wewnętrznej","Zawał w zakresie tętnicy tylnej mózgu (PCA)"],"keys":[1],"conf":"src","adapt":false,"gap":false,"src":"Sylabus PUM W03b · Wskazówka #5 · Fuller","why":"Zespół Wallenberga (niedrożność PICA lub tętnicy kręgowej) obejmuje boczną część opuszki: jądro dwuznaczne (IX/X — dysfagia, chrypka), drogę zstępującą współczulną (Horner po tej samej stronie), konar móżdżku dolny (ipsilateralna ataksja), jądro rdzeniowe n. V (czucie bólu/temp. po stronie ogniska na twarzy) i drogę rdzeniowo-wzgórzową (przeciwstronne kończyny). Piramidy leżą przyśrodkowo, dlatego brak niedowładu kończyn.","tip":"Zespół Wallenberga = zespół skrzyżowany BEZ niedowładu piramidowego kończyn.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"udar-q3","at":"udar","type":"mcq","mods":["2"],"topic":"Kwalifikacja rtPA/MT","stem":"71-letnia kobieta przywieziona na SOR po 95 minutach od nagłego wystąpienia afazji ruchowej i niedowładu połowiczego prawego (NIHSS 11 pkt). Glikemia 112 mg/dl, RR 172/92 mmHg, nie przyjmuje antykoagulantów. W pilnym TK głowy bez kontrastu nie uwidoczniono krwawienia ani wyraźnego ogniska niedokrwiennego. Prawidłowe postępowanie to:","opts":["Powtórzyć TK głowy za 24 h i włączyć alteplazę dopiero po pojawieniu się hipodensji","Rozpoznanie przemijającego ataku niedokrwiennego (TIA) i podanie 300 mg ASA p.o.","Natychmiastowe włączenie trombolizy i.v. (rtPA 0,9 mg/kg) oraz pilne angio-TK pod kątem trombektomii mechanicznej","Odroczyć leczenie reperfuzyjne do czasu wykonania punkcji lędźwiowej","Obniżyć ciśnienie skurczowe poniżej 130 mmHg przed decyzją o leczeniu"],"keys":[2],"conf":"src","adapt":false,"gap":true,"src":"Sylabus PUM Ćw TK07 · Wskazówka #6 · ESO","why":"W pierwszych godzinach udaru niedokrwiennego TK głowy bez kontrastu bywa prawidłowe — jego głównym zadaniem jest wykluczenie krwotoku śródmózgowego przed trombolizą. Przy czasie ≤4,5 h, RR <185/110 mmHg i braku przeciwwskazań należy natychmiast rozpocząć rtPA i równolegle wykonać angio-TK (okluzja LVO = wskazanie do MT).","tip":"Wskazówka PUM #6: Prawidłowe wczesne TK głowy NIE wyklucza udaru — przeciwnie, po wykluczeniu krwawienia kwalifikuje do rtPA.","zal":"Klasycznie w puli testowej: alteplaza (rtPA) 0,9 mg/kg i.v. (max 90 mg) podawana w oknie czasowym ≤4,5 h przy znanym czasie zachorowania.","akt":"Wytyczne ESO (2023) dopuszczają tenekteplazę (TNK) 0,25 mg/kg (max 25 mg) w pojedynczym bolusie i.v. jako alternatywę dla rtPA, a w udarach o nieznanym czasie / po przebudzeniu (wake-up stroke) lub w oknie 4,5–9 h pozwalają na kwalifikację na podstawie DWI-FLAIR mismatch lub perfuzji TK/MRI.","ans":"","reps":0,"bank":"modulowa"},{"id":"udar-q4","at":"udar","type":"mcq","mods":["2"],"topic":"Kwalifikacja rtPA/MT","stem":"66-letni chory w 2. godzinie ostrego udaru niedokrwiennego (NIHSS 16 pkt) ma wykluczony krwotok w TK głowy, bez innych przeciwwskazań do rtPA, lecz jego RR wynosi 198/108 mmHg. Po podaniu labetalolu i.v. ciśnienie spada do 176/98 mmHg, a angio-TK wykazuje okluzję odcinka M1 prawej MCA. Co należy zrobić?","opts":["Podać alteplazę i.v. i poczekać 60 minut na poprawę przed decyzją o trombektomii","Zrezygnować z alteplazy z powodu wcześniejszego RR >185/110 mmHg i zastosować wyłącznie ASA","Podać alteplazę i.v. i niezwłocznie przekazać chorego na trombektomię mechaniczną (MT), utrzymując RR <180/105 mmHg","Zastosować dożylną heparynę niefrakcjonowaną i obserwację na sali udarowej","Obniżyć RR poniżej 120/80 mmHg przed zabiegiem wewnątrznaczyniowym"],"keys":[2],"conf":"inf","adapt":false,"gap":true,"src":"Sylabus PUM Ćw TK07 · Wskazówka #6 · ESO/AHA","why":"Jeżeli RR uda się bezpiecznie obniżyć lekami i.v. poniżej 185/110 mmHg przed wlewem i utrzymywać <180/105 mmHg przez 24 h, tromboliza dożylna jest wskazana. Przy potwierdzonej okluzji dużego naczynia (ICA/M1) chorego kwalifikuje się natychmiast do trombektomii mechanicznej bez czekania na efekt kliniczny rtPA.","tip":"Nie czekaj na efekt rtPA przed wysłaniem chorego z LVO na pracownię hemodynamiki / radiologii zabiegowej.","zal":"Standardowa kwalifikacja egzaminacyjna do MT: okluzja dużego naczynia przedniego krążenia (ICA, M1) do 6 h od początku objawów przy niewielkich zmianach wczesnych (ASPECTS ≥6).","akt":"Aktualne wytyczne rozszerzają okno MT do 6–24 h przy zachowanej penumbrze w badaniu perfuzyjnym (DAWN/DEFUSE-3), dopuszczają MT w wybranych udarach z rozległym ogniskiem pierwotnym (ASPECTS 3–5) oraz w niedrożności tętnicy podstawnej (BA) do 24 h.","ans":"","reps":0,"bank":"modulowa"},{"id":"udar-q5","at":"udar","type":"mcq","mods":["2"],"topic":"Postępowanie i ICH","stem":"74-letni mężczyzna przewlekle leczony warfaryną z powodu migotania przedsionków (INR 3,2) doznał gwałtownego bólu głowy, wymiotów i lewostronnego niedowładu. W TK głowy świeży krwiak w obrębie prawej skorupy, RR 196/104 mmHg. Które postępowanie w pierwszej godzinie jest najwłaściwsze?","opts":["Obserwacja i powolna normalizacja INR samą witaminą K p.o. w ciągu 48 h","Pilne obniżenie skurczowego RR do 130–140 mmHg i.v. oraz podanie koncentratu 4F-PCC i witaminy K 10 mg i.v.","Podanie świeżo mrożonego osocza (FFP) jako jedynego leku i utrzymywanie RR >180 mmHg","Natychmiastowe wdrożenie mannitolu i deksametazonu w dużej dawce jako leczenia rutynowego","Podanie idarucyzumabu i.v. oraz klopidogrelu"],"keys":[1],"conf":"inf","adapt":false,"gap":true,"src":"Sylabus PUM W03b · Wytyczne ESO ICH / INTERACT3","why":"W ostrym krwotoku śródmózgowym (ICH) po VKA (INR >1,4) konieczne jest natychmiastowe odwrócenie antykoagulacji za pomocą koncentratu czynników zespołu protrombiny (4F-PCC) w połączeniu z witaminą K 10 mg i.v. oraz kontrolowane obniżenie SBP do 130–140 mmHg (labetalol/urapidyl). Idarucyzumab odwraca dabigatran, nie warfarynę; GKS są w udarze niezalecane.","tip":"Pamiętaj dopasowanie odtrutek: VKA → 4F-PCC + wit. K; dabigatran → idarucyzumab; rywaroksaban/apiksaban → andeksanet alfa lub 4F-PCC.","zal":"W starszych opracowaniach testowych jako sposób odwracania VKA podawano świeżo mrożone osocze (FFP) z witaminą K oraz bardziej liberalny cel ciśnienia (<160–180 mmHg).","akt":"Aktualne wytyczne ESO i AHA zalecają pakiet opieki (care bundle): szybkie obniżenie SBP do 130–140 mmHg (bez gwałtownego spadku >90 mmHg/h) oraz preferencyjnie 4F-PCC + witamina K i.v. zamiast FFP.","ans":"","reps":0,"bank":"modulowa"},{"id":"udar-q6","at":"udar","type":"mcq","mods":["2"],"topic":"Postępowanie i ICH","stem":"69-letni chory z udarem niedokrwiennym prawej półkuli mózgu zgłosił się w 14. godzinie od zachorowania (poza oknem do rtPA, bez okluzji dużego naczynia w angio-TK). W TK wykluczono krwotok, RR wynosi 204/106 mmHg, bez objawów rozwarstwienia aorty, zawału serca czy obrzęku płuc. Jakie jest właściwe postępowanie?","opts":["Gwałtowne obniżenie RR poniżej 140/90 mmHg kaptoprylem lub nifedypiną podjęzykowo","Włączenie ASA 150–300 mg oraz niefarmakologiczne/ostrożne utrzymanie obecnego RR (nie obniżać rutynowo poniżej 220/120 mmHg)","Podanie pełnej dawki enoksaparyny s.c. 2× dziennie od razu na SOR","Włączenie alteplazy w zmniejszonej dawce 0,6 mg/kg","Natychmiastowa trepanacja odbarczająca"],"keys":[1],"conf":"did","adapt":false,"gap":false,"src":"Sylabus PUM W03b · Stępień · Kozubski","why":"U chorych z udarem niedokrwiennym niekwalifikujących się do reperfuzji (rtPA/MT) obowiązuje zasada hipotensji permisywnej — w strefie penumbry autoregulacja mózgowa jest upośledzona i ciśnienie perfuzyjne zależy od RR systemowego. Nie obniża się RR, jeśli nie przekracza 220/120 mmHg (chyba że występują ostre powikłania narządowe). Po wykluczeniu krwotoku włącza się ASA.","tip":"Zapamiętaj dwa progi ciśnienia w udarze niedokrwiennym: Z rtPA <185/110 mmHg; BEZ rtPA <220/120 mmHg!","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"udar-q7","at":"udar","type":"mcq","mods":["2"],"topic":"SAH i zatoki","stem":"38-letnia kobieta zgłasza się z powodu nagłego, piorunującego bólu głowy („najsilniejszego w życiu”), który pojawił się 14 godzin wcześniej podczas wysiłku. W badaniu przytomna, bez niedowładu, niewielka sztywność karku. Pilne TK głowy bez kontrastu nie wykazuje krwi. Który krok jest obowiązkowy?","opts":["Wypisanie do domu z rozpoznaniem pierwszego napadu migreny i NLPZ","Wykonanie nakłucia lędźwiowego z oceną ksantochromii PMR (oraz angio-TK / wenografii przy utrzymującym się podejrzeniu)","Natychmiastowe włączenie kwasu acetylosalicylowego 300 mg","Powtórzenie samego TK bez kontrastu za 7 dni","Podanie sumatryptanu s.c. jako testu diagnostycznego"],"keys":[1],"conf":"src","adapt":false,"gap":true,"src":"Sylabus PUM W03b · Stępień · Wytyczne SAH","why":"Czułość TK głowy bez kontrastu w krwotoku podpajęczynówkowym (SAH) jest bliska 100% jedynie w pierwszych 6 godzinach, po czym maleje. Przy typowym wywiadzie piorunującego bólu głowy i ujemnym TK po >6–12 h obowiązkowe jest nakłucie lędźwiowe na obecność ksantochromii (rozkład hemoglobiny do bilirubiny) oraz diagnostyka naczyniowa (angio-TK/DSA w kierunku tętniaka lub MRV/CTV w kierunku CVST).","tip":"Po potwierdzeniu SAH włącz profilaktycznie nimodypinę 60 mg p.o. co 4 h na 21 dni i zabezpiecz tętniak.","zal":"W starszych podręcznikach w zapobieganiu i leczeniu skurczu naczyniowego po SAH opisywano terapię „triple-H” (hiperwolemia, hipertensja, hemodylucja).","akt":"Współczesne wytyczne odrzucają hiperwolemię i hemodylucję (powikłania płucne i obrzękowe): zalecają ścisłą normowolemię, doustną nimodypinę 60 mg co 4 h przez 21 dni oraz jedynie kontrolowaną indukowaną hipertensję przy objawowym opóźnionym niedokrwieniu (DCI) po zabezpieczeniu tętniaka.","ans":"","reps":0,"bank":"modulowa"},{"id":"pad-q1","at":"padaczka","type":"mcq","mods":["4"],"topic":"Klasyfikacja ILAE i semiologia","stem":"Zgodnie z praktyczną definicją ILAE (2014) padaczkę można rozpoznać już po JEDNYM napadzie nieprowokowanym, jeżeli:","opts":["napad wystąpił podczas gorączki lub w przebiegu ostrej hipoglikemii (<40 mg/dl)","prawdopodobieństwo wystąpienia kolejnych napadów w ciągu najbliższych 10 lat wynosi co najmniej 60% (np. ognisko strukturalne w MRI i zmiany padaczkokształtne w EEG)","u pacjenta stwierdzono prawidłowe EEG i prawidłowe MRI mózgu, ale napad trwał powyżej 60 sekund","był to izolowany napad w ciągu pierwszych 7 dni po ostrym udarze niedokrwiennym mózgu"],"keys":[1],"conf":"src","adapt":false,"gap":true,"src":"ILAE 2014; Podemski wyd. IV; Sylabus W03c","why":"Praktyczna definicja ILAE dopuszcza rozpoznanie padaczki w trzech sytuacjach: (1) ≥2 napady nieprowokowane w odstępie >24 h, (2) 1 napad nieprowokowany przy ryzyku nawrotu ≥60% w kolejnych 10 latach (porównywalnym do ryzyka po 2 napadach), (3) rozpoznanie określonego zespołu padaczkowego. Napady w ostrej fazie udaru (≤7 dni), hipoglikemii czy gorączce są napadami prowokowanymi (objawowymi ostrymi) i nie upoważniają do rozpoznania padaczki.","tip":"Odróżniaj napad ostry objawowy (np. w przebiegu hiponatremii lub świeżego udaru) od nieprowokowanego — pierwszy nie wymaga przewlekłego leczenia przeciwpadaczkowego po usunięciu przyczyny.","zal":"W starszych opracowaniach testowych warunkiem rozpoznania padaczki bywało wyłącznie wystąpienie co najmniej dwóch samoistnych napadów w wywiadzie.","akt":"Obowiązująca definicja ILAE (2014) pozwala rozpoznać padaczkę już po 1 napadzie nieprowokowanym, jeśli ryzyko nawrotu w ciągu 10 lat wynosi ≥60% (np. blizna poudarowa/guz + iglice w EEG) lub spełnione są kryteria zespołu padaczkowego.","ans":"","reps":0,"bank":"modulowa"},{"id":"pad-q2","at":"padaczka","type":"mcq","mods":["4"],"topic":"Klasyfikacja ILAE i semiologia","stem":"26-letni pacjent zgłasza epizody trwające około 60–90 sekund, poprzedzone nagłym uczuciem gorąca w nadbrzuszu i wrażeniem déjà vu. Świadkowie opisują zastyganie wzroku, mlaskanie oraz skubanie rękawa, a po ustąpieniu epizodu chory przez kilka minut jest zdezorientowany. Według klasyfikacji ILAE 2017 jest to:","opts":["uogólniony napad nieświadomości (typowy)","napad ogniskowy z zaburzoną świadomością (dawniej złożony częściowy)","napad ogniskowy z zachowaną świadomością bez automatyzmów","psychogenny napad niepadaczkowy (PNES)","napad atoniczny"],"keys":[1],"conf":"did","adapt":false,"gap":false,"src":"ILAE 2017; Stępień Neurologia t. II","why":"Aura nadbrzuszna i déjà vu wskazują na ogniskowy początek w przyśrodkowym płacie skroniowym, po czym następuje utrata kontaktu z otoczeniem, automatyzmy oralne i manualne oraz przedłużone splątanie ponapadowe — to klasyczny napad ogniskowy z zaburzoną świadomością (FIAS, dawniej częściowy złożony). Typowy napad nieświadomości trwa 5–15 s, zaczyna się i kończy nagle bez aury i bez splątania ponapadowego.","tip":"Aura = początek napadu ogniskowego z zachowaną świadomością. Automatyzmy i splątanie ponapadowe odróżniają napad skroniowy od napadu nieświadomości.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"pad-q3","at":"padaczka","type":"mcq","mods":["4"],"topic":"Diagnostyka i EEG","stem":"20-letnia studentka zgłosiła się po pierwszym w życiu uogólnionym napadzie toniczno-klonicznym po nieprzespanej nocy. W wywiadzie od 2 lat miewa rano po przebudzeniu krótkie, obustronne szarpnięcia kończyn górnych („upuszczanie lub rozlanie kawy”). Rutynowe spoczynkowe EEG jest prawidłowe. Które stwierdzenie jest NAJBARDZIEJ trafne?","opts":["prawidłowe spoczynkowe EEG wyklucza padaczkę i nakazuje zakończenie diagnostyki","obraz przemawia za młodzieńczą padaczką miokloniczną (JME); należy powtórzyć EEG po deprywacji snu z fotostymulacją (poszukując poliiglica–fala 4–6 Hz)","wskazane jest natychmiastowe włączenie karbamazepiny jako leku I rzutu","poranne mioklonie świadczą o ognisku w korze ruchowej i nakazują pilne leczenie neurochirurgiczne"],"keys":[1],"conf":"src","adapt":false,"gap":false,"src":"Sylabus Sem TK04; Kozubski & Liberski","why":"Poranne mioklonie ramion prowokowane brakiem snu oraz napad GTC u młodego dorosłego to klasyczny obraz młodzieńczej padaczki mioklonicznej (JME). Pojedyncze spoczynkowe EEG ma czułość zaledwie ~30–50%, więc prawidłowy zapis nie wyklucza padaczki — zwiększa ją powtórzenie badania z aktywacją (hiperwentylacja, fotostymulacja) oraz po deprywacji snu (typowe uogólnione zespoły poliiglica–fala 4–6 Hz).","tip":"Prawidłowe pojedyncze spoczynkowe EEG NIE wyklucza padaczki. W JME nigdy nie włączaj karbamazepiny, okskarbazepiny ani fenytoiny — nasilają mioklonie!","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"pad-q4","at":"padaczka","type":"mcq","mods":["4"],"topic":"Stan padaczkowy i różnicowanie","stem":"29-letni mężczyzna podczas pobierania krwi poczuł mroczki przed oczami, zbledł i stracił przytomność. W pozycji półleżącej przez około 8 sekund obserwowano kilka nieregularnych zrywań kończyn górnych. Bezpośrednio po ocknięciu był zorientowany co do miejsca i czasu, nie przygryzł języka i nie oddał moczu. Jakie jest właściwe rozpoznanie i pierwszy krok?","opts":["napad toniczno-kloniczny — należy pilnie włączyć walproinian przewlekle","omdlenie drgawkowe (odruchowe) — należy wykonać 12-odprowadzeniowe EKG oraz zebrać wywiad kardiologiczny, bez włączania leków przeciwpadaczkowych","stan padaczkowy — należy podać lorazepam 4 mg i.v.","napad ogniskowy czołowy — należy skierować pacjenta wyłącznie na wideo-EEG bez badania serca"],"keys":[1],"conf":"inf","adapt":false,"gap":false,"src":"Fuller 2022; Sylabus Ćw TK06; Moduł [3]","why":"Krótkotrwała hipoperfuzja mózgu w omdleniu (stres, ból, pozycja stojąca, bladość, mroczki) często wywołuje kilka asynchronicznych mioklonii („omdlenie drgawkowe”), co bywa błędnie brane za padaczkę. Kluczowe dla omdlenia są wyzwalacz wazowagalny, czas utraty przytomności zwykle <20 s, brak sinicy i brak splątania ponapadowego. Każdy chory po utracie przytomności wymaga 12-odprowadzeniowego EKG (wykluczenie arytmii i zespołu długiego QT).","tip":"Krótkie szarpnięcia w omdleniu z szybkim powrotem pełnej świadomości ≠ padaczka. Zawsze oceń EKG zanim pomyślisz o LPP.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"pad-q5","at":"padaczka","type":"mcq","mods":["4"],"topic":"Farmakoterapia LPP","stem":"U 23-letniej kobiety w wieku rozrodczym z nowo rozpoznaną młodzieńczą padaczką miokloniczną (JME) leczeniem przeciwpadaczkowym pierwszego wyboru jest:","opts":["karbamazepina w monoterapii","fenytoina w monoterapii","lewetyracetam (lub lamotrygina przy zachowaniu ostrożności co do ewentualnego nasilenia mioklonii)","kwas walproinowy jako bezwzględny lek pierwszego rzutu niezależnie od antykoncepcji","etosuksymid w monoterapii"],"keys":[2],"conf":"src","adapt":false,"gap":true,"src":"EMA PRAC 2018; PTN; ILAE; Podemski","why":"Ze względu na wysoką teratogenność kwasu walproinowego (~10–11% dużych wad wrodzonych, w tym rozszczep kręgosłupa, oraz 30–40% zaburzeń neurorozwojowych), u kobiet w wieku rozrodczym jest on przeciwwskazany, chyba że inne LPP są nieskuteczne i spełnione są wymogi Programu Zapobiegania Ciąży. Lekiem I rzutu w JME u kobiet jest lewetyracetam (ewentualnie lamotrygina, choć u części chorych może nasilać mioklonie). Karbamazepina i fenytoina pogarszają napady miokloniczne, a etosuksymid nie chroni przed GTC.","tip":"Na egzaminie kojarz dwa zakazy w jednym pytaniu: walproinian (teratogenność u kobiet w wieku rozrodczym) + blokery Na⁺ (karbamazepina/fenytoina nasilają JME i absence).","zal":"W starszych skryptach walproinian bywał wskazywany jako uniwersalny lek pierwszego rzutu we wszystkich padaczkach uogólnionych idiopatycznych.","akt":"Wytyczne EMA, PTN i ILAE zakazują stosowania walproinianu jako leku pierwszego wyboru u dziewcząt i kobiet w wieku rozrodczym — preferuje się lewetyracetam lub lamotryginę.","ans":"","reps":0,"bank":"modulowa"},{"id":"pad-q6","at":"padaczka","type":"mcq","mods":["4"],"topic":"Stan padaczkowy i różnicowanie","stem":"Do SOR przywieziono 45-letniego chorego z uogólnionymi drgawkami toniczno-klonicznymi trwającymi nieprzerwanie od 7 minut. Zespół ratownictwa nie zdołał jeszcze uzyskać dostępu dożylnego, glikemia włośniczkowa wynosi 114 mg/dl. Jakie powinno być NATYCHMIASTOWE postępowanie?","opts":["czekać z podaniem leków do pełnych 30 minut trwania napadu (klasyczna definicja stanu padaczkowego)","rozpoznać drgawkowy stan padaczkowy (przekroczony próg t₁ = 5 min) i natychmiast podać midazolam 10 mg i.m. (ew. donosowo/dopoliczkowo), nie opóźniając terapii próbami kaniulacji żył","natychmiast wykonać punkcję lędźwiową przed stabilizacją chorego","podać wyłącznie 2 mg diazepamu i.m. i wykonać planowe EEG za 24 h"],"keys":[1],"conf":"src","adapt":false,"gap":true,"src":"ILAE 2015; AES 2016; RAMPART; Meta Hub t11","why":"Według definicji ILAE (2015) punkt czasowy t₁ = 5 min dla drgawkowego stanu padaczkowego oznacza moment rozpoznania SE i natychmiastowego podania pełnej dawki benzodiazepiny (I linia). Badanie RAMPART wykazało co najmniej równorzędną skuteczność i szybszy czas podania midazolamu 10 mg i.m. w porównaniu z lorazepamem i.v., gdy brak wkłucia dożylnego.","tip":"Zapamiętaj dwa progi ILAE: t₁ = 5 min (czas rozpoczęcia leczenia ratunkowego SE), t₂ = 30 min (czas ryzyka nieodwracalnego uszkodzenia neuronów).","zal":"Starsze podręczniki definiowały stan padaczkowy dopiero jako napad (lub serię napadów bez powrotu świadomości) trwający ≥30 minut.","akt":"Aktualnie (ILAE 2015, AES, PTN) leczenie drgawkowego SE wdraża się już po t₁ = 5 minutach ciągłych drgawek; 30 minut stanowi próg t₂ (ryzyko trwałych następstw neuronalnych).","ans":"","reps":0,"bank":"modulowa"},{"id":"pad-q7","at":"padaczka","type":"mcq","mods":["4"],"topic":"Farmakoterapia LPP","stem":"U 80-kilogramowego chorego z drgawkowym stanem padaczkowym po 2 pełnych dawkach lorazepamu i.v. (łącznie 8 mg) w 20. minucie napadu drgawki nadal się utrzymują. Według randomizowanego badania ESETT w drugiej fazie leczenia (20–40 min) równorzędną skuteczność (~45–47%) wykazują dożylne dawki nasycające:","opts":["lewetyracetam 60 mg/kg (maks. 4500 mg), walproinian 40 mg/kg (maks. 3000 mg) lub fosfenytoina/fenytoina 20 mg/kg (maks. 1500 mg)","etosuksymid 15 mg/kg i.v. lub karbamazepina 10 mg/kg i.v.","kolejne 4 bolusy diazepamu i.v. bez leku II linii przed 60. minutą","wyłącznie tiopental w dawce 50 mg/kg i.v. bez intubacji"],"keys":[0],"conf":"own","adapt":false,"gap":false,"src":"ESETT (NEJM 2019); AES; Kalkulator SE Hubu","why":"Badanie ESETT potwierdziło porównywalną skuteczność (~45–47% przerwania SE w ciągu 60 min) oraz bezpieczeństwo trzech leków II rzutu podawanych i.v. w wysokich dawkach nasycających: lewetyracetamu 60 mg/kg (maks. 4500 mg), walproinianu 40 mg/kg (maks. 3000 mg) oraz fosfenytoiny 20 mg PE/kg (maks. 1500 mg; w warunkach polskich dostępna fenytoina 20 mg/kg maks. 1500 mg ≤50 mg/min pod kontrolą EKG i BP). Po >40 min opornego SE (RSE) wdraża się leki znieczulenia ogólnego na OIT z cEEG.","tip":"Przelicz szybko dawki dla 80 kg: LEV = 4500 mg (limit), VPA = 3000 mg (limit), PHT = 1500 mg (limit). Lewetyracetam ma najmniej interakcji i przeciwwskazań.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"bad-q1","at":"badanie","type":"mcq","mods":["5"],"topic":"Badanie U02 i UMN/LMN","stem":"Który zestaw objawów jest najbardziej charakterystyczny dla utrwalonego uszkodzenia dolnego neuronu ruchowego (LMN) w porównaniu z uszkodzeniem górnego neuronu ruchowego (UMN)?","opts":["wzmożone napięcie typu „scyzoryka”, wygórowane odruchy głębokie i objaw Babińskiego","obniżone napięcie mięśniowe (wiotkość), zanik mięśni, fascykulacje oraz osłabienie lub zniesienie odruchów głębokich","sztywność typu „koła zębatego”, drżenie spoczynkowe i prawidłowe odruchy głębokie","zniesienie odruchów powierzchownych brzusznych, klonus stopy i brak zaników mięśniowych","wygórowane odruchy głębokie przy jednoczesnych fascykulacjach i zachowanym czuciu"],"keys":[1],"conf":"src","adapt":false,"gap":true,"src":"Wskazówka PUM #7 · Sem TK01 / Ćw TK01","why":"Uszkodzenie dolnego neuronu ruchowego (róg przedni rdzenia, jądro ruchowe pnia lub włókno nerwu obwodowego) przerywa ramię odśrodkowe łuku odruchowego, co skutkuje wiotkością, wczesnym zanikiem neurogennym, fascykulacjami i hipo-/arefleksją bez objawu Babińskiego. Wygórowane odruchy z klonusem, spastycznością i Babińskim (+) cechują UMN, a opcja E odpowiada zespołowi mieszanemu (SLA).","tip":"Wskazówka PUM #7: UMN = spastyczność + hiperrefleksja + Babiński (+); LMN = wiotkość + zaniki + fascykulacje + arefleksja.","zal":"W pytaniach testowych przyjmuje się schematycznie: UMN = spastyczność, wygórowane odruchy i Babiński (+), a LMN = wiotkość, zaniki, fascykulacje i zniesione odruchy.","akt":"W praktyce klinicznej w pierwszych godzinach/dniach ostrego rozległego udaru lub urazu rdzenia (faza szoku mózgowego/rdzeniowego) świeże uszkodzenie UMN przebiega przejściowo z wiotkością i zniesieniem odruchów, zanim rozwinie się spastyczność.","ans":"","reps":0,"bank":"modulowa"},{"id":"bad-q2","at":"badanie","type":"mcq","mods":["5"],"topic":"Móżdżek vs sznury tylne","stem":"64-letni chory po częściowej resekcji żołądka zgłasza mrowienia stóp oraz gwałtowne tracenie równowagi podczas mycia twarzy i zamykania oczu pod prysznicem. W badaniu przy oczach otwartych stoi stabilnie, nie ma dysmetrii ani oczopląsu, natomiast w próbie Romberga po zamknięciu oczu natychmiast chwieje się i upada; na kostkach nie odczuwa wibracji kamertonu 128 Hz. Która struktura jest uszkodzona?","opts":["prawa półkula móżdżku","robak móżdżku","sznury tylne rdzenia kręgowego (ataksja czuciowa)","droga korowo-rdzeniowa w odcinku lędźwiowym"],"keys":[2],"conf":"src","adapt":false,"gap":true,"src":"Wskazówka PUM #10 · Podemski / Fuller U02","why":"Pacjent z uszkodzeniem sznurów tylnych (pęczki smukły i klinowaty) kompensuje ubytek propriocepcji wzrokiem — stoi stabilnie z otwartymi oczami i traci równowagę dopiero po ich zamknięciu (próba Romberga wybitnie dodatnia), z jednoczesnym zniesieniem czucia wibracji i ułożenia. W zespole móżdżkowym chory chwieje się już przy oczach otwartych.","tip":"Wskazówka PUM #10: Dodatnia próba Romberga nie jest swoista dla móżdżku — bada sznury tylne (B12, kiła) oraz narząd przedsionkowy.","zal":"Klucz testowy z Wskazówki #10: próba Romberga (+) i utrata czucia wibracji różnicują zwyrodnienie sznurów tylnych od zespołu móżdżkowego.","akt":"W niedoborze witaminy B12 (zwyrodnienie powrózkowe rdzenia) zajęciu sznurów tylnych często towarzyszy uszkodzenie sznurów bocznych (Babiński +) oraz polineuropatia (zniesione odruchy skokowe); nigdy nie podawaj samego kwasu foliowego bez wyrównania B12.","ans":"","reps":0,"bank":"modulowa"},{"id":"bad-q3","at":"badanie","type":"mcq","mods":["6"],"topic":"Nerwy czaszkowe I–XII","stem":"U pacjenta stwierdzono całkowite opadnięcie prawej powieki górnej (ptoza), ustawienie prawej gałki ocznej „w dół i na zewnątrz” oraz poszerzoną, niereagującą na światło prawą źrenicę. Który nerw czaszkowy uległ uszkodzeniu?","opts":["prawy nerw odwodzący (VI)","prawy nerw bloczkowy (IV)","prawy nerw okoruchowy (III)","prawa gałąź oczna nerwu trójdzielnego (V1)"],"keys":[2],"conf":"src","adapt":false,"gap":true,"src":"Wskazówka PUM #1 · Sem TK10","why":"Nerw III unerwia mięśnie prosty górny, dolny, przyśrodkowy, skośny dolny, dźwigacz powieki górnej oraz włókna przywspółczulne zwieracza źrenicy. Jego porażenie pozostawia niezrównoważone działanie m. prostego bocznego (VI) i skośnego górnego (IV), ustawiając oko „w dół i na zewnątrz”, z ptozą i szeroką źrenicą.","tip":"Wskazówka PUM #1: III = ptoza + oko w dół i na zewnątrz + szeroka źrenica; IV = diplopia przy schodzeniu po schodach; VI = zez zbieżny.","zal":"W klasycznym opisie testowym porażenie n. III daje łącznie ptozę, ustawienie gałki w dół i na zewnątrz oraz poszerzoną sztywną źrenicę.","akt":"Klinicznie (ESO/AAN) bolesne porażenie n. III z poszerzoną źrenicą jest alarmem ucisku przez tętniak tętnicy łączącej tylnej (pilne angio-TK/MR) lub wgłobienie; natomiast mikronaczyniowe porażenie n. III w cukrzycy zazwyczaj oszczędza źrenicę.","ans":"","reps":0,"bank":"modulowa"},{"id":"bad-q4","at":"badanie","type":"mcq","mods":["6"],"topic":"Nerwy czaszkowe I–XII","stem":"Chory zgłosił się z całkowitym zniesieniem ruchów lewej gałki ocznej (porażenie nerwów III, IV i VI), ptozą, poszerzoną lewą źrenicą oraz brakiem czucia na lewym czole i zniesieniem lewego odruchu rogówkowego. Ostrość wzroku i dno oka lewego są prawidłowe. Który zespół rozpoznasz?","opts":["zespół szczeliny oczodołowej górnej","zespół szczytu oczodołu","zespół Wallenberga (boczny opuszki)","zespół kąta mostowo-móżdżkowego","zespół Fostera-Kennedy’ego"],"keys":[0],"conf":"src","adapt":false,"gap":false,"src":"Wskazówka PUM #4 · Sem TK10","why":"Przez szczelinę oczodołową górną przechodzą nerwy III, IV, VI oraz gałąź oczna nerwu V (V1 — czucie czoła i ramię dośrodkowe odruchu rogówkowego). Nerw wzrokowy (II) biegnie oddzielnie przez kanał wzrokowy, dlatego jego zaoszczędzenie różnicuje zespół szczeliny oczodołowej górnej od zespołu szczytu oczodołu.","tip":"Wskazówka PUM #4: Szczelina oczodołowa górna = III, IV, VI + V1 (bez II). Gdy dołącza ślepota/RAPD (n. II) → szczyt oczodołu.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"bad-q5","at":"badanie","type":"mcq","mods":["6"],"topic":"Nerwy czaszkowe I–XII","stem":"70-letni mężczyzna trafił na SOR z nagłym wygładzeniem prawego fałdu nosowo-wargowego i opadnięciem prawego kącika ust. Podczas badania potrafi jednak symetrycznie zmarszczyć czoło i mocno zacisnąć obie powieki, a w prawej kończynie górnej stwierdza się spadek siły do 4/5. Jak zlokalizujesz uszkodzenie nerwu VII?","opts":["obwodowe porażenie prawego nerwu VII (porażenie Bella)","uszkodzenie jądra nerwu VII w prawym moście","ośrodkowe (nadjądrowe) uszkodzenie drogi korowo-jądrowej w lewej półkuli mózgu","uszkodzenie nerwu VII w przewodzie słuchowym wewnętrznym po prawej"],"keys":[2],"conf":"src","adapt":false,"gap":false,"src":"Wskazówka PUM #3 · Sem TK10","why":"Górne piętro twarzy (m. czołowy i okrężny oka) ma obustronne unerwienie korowe, dlatego w uszkodzeniu ośrodkowym (nadjądrowym) zostaje zaoszczędzone. Niedowład obejmuje dolne 2/3 twarzy po stronie przeciwnej do ogniska w lewej półkuli (współistnieje tu z prawostronnym niedowładem kończyny górnej w unaczynieniu lewej MCA).","tip":"Wskazówka PUM #3: Zawsze poleć choremu zmarszczyć czoło i zacisnąć powieki — zaoszczędzone czoło wyklucza porażenie Bella.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"bad-q6","at":"badanie","type":"mcq","mods":["6"],"topic":"Nerwy czaszkowe I–XII","stem":"Podczas badania gardła u chorego z chrypką i dysfagią przy fonacji głoski „aaa” stwierdzono opadnięcie prawego łuku podniebiennego oraz przesunięcie języczka i tylnej ściany gardła w stronę lewą (objaw firanki Verneta). Język wysuwa się prosto, bez zaniku. Uszkodzenie których nerwów odpowiada za ten obraz?","opts":["lewych nerwów IX i X","prawego nerwu podjęzykowego (XII)","lewego nerwu podjęzykowego (XII)","prawych nerwów językowo-gardłowego (IX) i błędnego (X)"],"keys":[3],"conf":"src","adapt":false,"gap":false,"src":"Wskazówka PUM #2 · Sem TK10","why":"W niedowładzie podniebienia i ściany gardła (IX, X) porażone mięśnie strony prawej są wiotkie, dlatego zdrowa strona lewa pociąga języczek oraz tylną ścianę gardła w stronę ZDROWĄ (w lewo). W uszkodzeniu nerwu XII wysunięty język zbaczałby odwrotnie — w stronę CHORĄ.","tip":"Wskazówka PUM #2: Języczek (n. X) ucieka w stronę ZDROWĄ; język (n. XII) zbacza w stronę CHORĄ.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"bad-q7","at":"badanie","type":"mcq","mods":["6"],"topic":"Afazja i dyzartria","stem":"U praworęcznego pacjenta po udarze mowa spontaniczna jest płynna i wielomówna, ale zawiera liczne parafazje głoskowe oraz neologizmy. Chory nie rozumie poleceń słownych, nie potrafi powtarzać wypowiadanych przez badającego słów i nie ma niedowładu kończyn. Jaki typ zaburzenia mowy występuje u tego pacjenta?","opts":["afazja ruchowa (Broca)","afazja czuciowa (Wernickego)","afazja przewodzenia (kondukcyjna)","dyzartria móżdżkowa (mowa skandowana)","afazja globalna"],"keys":[1],"conf":"inf","adapt":false,"gap":false,"src":"Ćw TK08 · Podemski / Stępień","why":"Płynna mowa z parafazjami i neologizmami przy głębokim zaburzeniu rozumienia oraz powtarzania i braku niedowładu ruchowego odpowiada afazji czuciowej (Wernickego, tylna część lewego zakrętu skroniowego górnego). W afazji przewodzenia rozumienie jest zachowane, w afazji Broca mowa jest niepłynna przy zachowanym rozumieniu, a w dyzartrii zachowane jest rozumienie i struktura języka.","tip":"Schemat przy łóżku: Broca = niepłynna + rozumie; Wernicke = płynna + nie rozumie; Przewodzenia = płynna + rozumie + nie powtarza.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"bol-q1","at":"bole","type":"mcq","mods":["7"],"topic":"Klasyfikacja, SNOOP i migrena","stem":"48-letnia kobieta bez wcześniejszego wywiadu bólów głowy zgłasza nagły, najsilniejszy w życiu ból okolicy potylicznej, który osiągnął maksimum w ciągu 30 sekund podczas wysiłku fizycznego, z nudnościami i światłowstrętem. TK głowy bez kontrastu wykonane w 10. godzinie od początku objawów nie wykazuje krwi. Jakie jest właściwe dalsze postępowanie?","opts":["Rozpoznanie pierwszego w życiu napadu migreny bez aury i podanie sumatryptanu 6 mg s.c.","Wykluczenie krwotoku na podstawie prawidłowego TK i wypisanie chorej z NLPZ","Pilne wykonanie nakłucia lędźwiowego (ocena ksantochromii) oraz/lub angio-TK naczyń mózgowych w kierunku SAH","Zlecenie planowego MRI w trybie ambulatoryjnym za 4 tygodnie oraz propranololu p.o.","Włączenie karbamazepiny w dawce 200 mg/d w kierunku neuralgii potylicznej"],"keys":[2],"conf":"did","adapt":false,"gap":true,"src":"Sylabus PUM [7] · W03a / Sem TK11 · SNOOP10","why":"Piorunujący ból głowy (szczyt <1 min) to główna czerwona flaga SNOOP10 nakazująca wykluczenie krwotoku podpajęczynówkowego (SAH). Po upływie >6 h od początku objawów czułość samego TK bez kontrastu spada, więc ujemny wynik TK NIE wyklucza SAH i wymaga pilnego nakłucia lędźwiowego (ksantochromia) lub angio-TK.","tip":"Nigdy nie rozpoznawaj migreny „de novo” przy piorunującym bólu głowy. Granica wysokiej czułości TK w SAH to pierwsze 6 godzin.","zal":"W klasycznym schemacie egzaminacyjnym przy podejrzeniu SAH z ujemnym TK zawsze wykonuje się punkcję lędźwiową (ocena ksantochromii/krwinkotoku).","akt":"Kryterium 6 godzin (Ottawa SAH / ESO): czułość nowoczesnego TK w pierwszych 6 h od początku bólu wynosi niemal 100%, natomiast >6 h obowiązkowe jest nakłucie lędźwiowe lub angio-TK.","ans":"","reps":0,"bank":"modulowa"},{"id":"bol-q2","at":"bole","type":"mcq","mods":["7"],"topic":"Klasyfikacja, SNOOP i migrena","stem":"32-letnia pacjentka z migreną z typową aurą wzrokową (mroczki migoczące trwające ok. 25 minut przed napadem) ma 8 dni bólowych w miesiącu i przyjmuje doustną antykoncepcję zawierającą etynyloestradiol. Wywiad kardiologiczny jest ujemny. Które stwierdzenie jest prawdziwe?","opts":["W profilaktyce migreny lekiem pierwszego wyboru u tej pacjentki jest kwas walproinowy","Sumatryptan należy podać natychmiast na początku aury wzrokowej, aby zapobiec fazie bólowej","Doustna antykoncepcja estrogenowa jest przeciwwskazana z powodu zwiększonego ryzyka udaru niedokrwiennego mózgu","Łączne podanie sumatryptanu i winianu ergotaminy podczas jednego napadu jest zalecanym standardem w migrenie z aurą"],"keys":[2],"conf":"inf","adapt":false,"gap":true,"src":"Sylabus PUM [7] · Sem TK11 · IHS / PTBG","why":"Migrena z aurą stanowi istotny czynnik ryzyka udaru niedokrwiennego, a stosowanie złożonej antykoncepcji zawierającej estrogeny dodatkowo to ryzyko zwielokrotnia i jest przeciwwskazane. Kwas walproinowy jest bezwzględnie odradzany u kobiet w wieku rozrodczym (teratogenność). Tryptany podaje się na początku fazy bólu (nie w aurze) i nie wolno łączyć ich z ergotaminą (<24 h).","tip":"Zapamiętaj triadę pułapek w migrenie: brak estrogenów w migrenie z aurą, brak walproinianu u kobiet w wieku rozrodczym i zakaz łączenia tryptanu z ergotaminą.","zal":"Tradycyjna profilaktyka pierwszego rzutu obejmuje β-blokery (propranolol), topiramat, amitryptylinę oraz (poza ciążą/wiekiem rozrodczym) walproinian; leczenie doraźne to NLPZ i tryptany.","akt":"Aktualne wytyczne IHS/EAN rekomendują przeciwciała anty-CGRP (erenumab, fremanezumab, galkanezumab, eptinezumab) i gepanty (rimegepant, atogepant) także wcześnie w profilaktyce, a rimegepant doraźnie przy przeciwwskazaniach naczyniowych do tryptanów.","ans":"","reps":0,"bank":"modulowa"},{"id":"bol-q3","at":"bole","type":"mcq","mods":["7"],"topic":"Klasterowy i neuralgia V","stem":"36-letni mężczyzna od 2 tygodni budzi się codziennie ok. godz. 02:00 z powodu rozrywającego bólu za lewym okiem trwającego 45 minut. Podczas ataku chodzi niespokojnie po pokoju, ma zaczerwienioną lewą spojówkę, obfite łzawienie, wodnisty wyciek z lewego nozdrza oraz niepełny zespół Hornera po stronie lewej. Które postępowanie przerywa taki napad najszybciej?","opts":["Karbamazepina 400 mg p.o. jednorazowo","100% tlen przez maskę z rezerwuarem (12–15 L/min przez 15 min) oraz/lub sumatryptan 6 mg s.c.","Ibuprofen 400 mg p.o. i leżenie w zaciemnionym, cichym pomieszczeniu","Prednizon 60 mg p.o. jako jedyny lek doraźny działający w kilka minut"],"keys":[1],"conf":"src","adapt":false,"gap":false,"src":"Sylabus PUM [7] · Wykład TK03 · TAC","why":"Obraz odpowiada klasterowemu bólowi głowy (czas trwania 15–180 min, okołodobowa powtarzalność w nocy, pobudzenie psychoruchowe i ipsilateralne objawy autonomiczne). Leczeniem przerywającym I rzutu są inhalacje 100% tlenu o wysokim przepływie (12–15 L/min) oraz podskórny sumatryptan 6 mg. Prednizon służy do krótkiej terapii pomostowej przed osiągnięciem efektu werapamilu, a nie do przerywania pojedynczego napadu.","tip":"Klaster = pobudzenie + łzawienie/Horner + 15–180 min. Doraźnie: 100% O₂ + sumatryptan s.c.; profilaktycznie: werapamil (z kontrolą EKG).","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"bol-q4","at":"bole","type":"mcq","mods":["7"],"topic":"Klasterowy i neuralgia V","stem":"29-letnia kobieta od 3 tygodni odczuwa napadowe, trwające ułamek sekundy przeszycia przypominające „rażenie prądem” w zakresie szczęki i żuchwy po obu stronach twarzy, wyzwalane myciem zębów i lekkim dotykiem. W badaniu stwierdzono osłabienie odruchu rogówkowego po stronie prawej. Jakie jest najwłaściwsze postępowanie?","opts":["Rozpoznanie pierwotnej neuralgii nerwu V i włączenie paracetamolu z ibuprofenem","Pilne MRI mózgu z kontrastem w celu wykluczenia wtórnej neuralgii (np. SM lub guza kąta mostowo-móżdżkowego) oraz włączenie karbamazepiny/okskarbazepiny","Podanie sumatryptanu 6 mg s.c. i obserwacja przez 4 tygodnie","Zastosowanie indometacyny jako swoistego leku pierwszego rzutu w neuralgii nerwu trójdzielnego","Skierowanie chorej wyłącznie na ekstrakcję zębów przedtrzonowych"],"keys":[1],"conf":"did","adapt":false,"gap":false,"src":"Sylabus PUM [7] · Wykład TK03 / Ćw TK04 · Neuralgia V","why":"Młody wiek (<40 r.ż.), obustronne występowanie bólu oraz ubytek w badaniu nerwu V (osłabiony odruch rogówkowy) są czerwonymi flagami neuralgii objawowej — klasycznie w przebiegu stwardnienia rozsianego (SM) lub guza kąta mostowo-móżdżkowego. Konieczne jest MRI z kontrastem, a leczeniem farmakologicznym I rzutu pozostaje karbamazepina (lub okskarbazepina). Indometacyna jest testem/lekiem swoistym dla hemikranii napadowej.","tip":"Młody wiek + neuralgia V (zwłaszcza obustronna lub z ubytkiem czucia/odruchu rogówkowego) → pomyśl o stwardnieniu rozsianym [9] i zleć MRI!","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"bol-q5","at":"bole","type":"mcq","mods":["8"],"topic":"Radikulopatie C / L-S","stem":"44-letni mężczyzna skarży się na ból krzyża promieniujący po bocznej stronie uda i podudzia aż do grzbietu stopy i palucha po stronie prawej. W badaniu: dodatni objaw Lasègue’a przy 40°, osłabienie zgięcia grzbietowego stopy i prostowania palucha po prawej (nie potrafi stanąć na pięcie), natomiast odruch kolanowy i skokowy są obustronnie żywe i symetryczne. Który korzeń nerwowy jest uciśnięty?","opts":["Korzeń L3 (przepuklina na poziomie L2–L3)","Korzeń L4 (przepuklina na poziomie L3–L4)","Korzeń L5 (najczęściej przepuklina na poziomie L4–L5)","Korzeń S1 (najczęściej przepuklina na poziomie L5–S1)"],"keys":[2],"conf":"inf","adapt":false,"gap":false,"src":"Sylabus PUM [8] · W03h / Ćw TK12 · Topografia L4–S1","why":"Zespół korzeniowy L5 (typowo z przepukliny krążka L4–L5) daje ból wzdłuż bocznej powierzchni kończyny do grzbietu stopy i palucha, osłabienie prostowników stopy i palucha (trudność w staniu na piętach, opadanie stopy) oraz PRAWIDŁOWE odruchy kolanowy (L3–L4) i skokowy (S1). Odruch skokowy zanika w uszkodzeniu S1 (przepuklina L5–S1).","tip":"Pułapka topograficzna: przepuklina L4–L5 uciska korzeń L5 (brak zaburzeń odruchów głębokich!), a przepuklina L5–S1 uciska S1 (brak odruchu skokowego).","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"bol-q6","at":"bole","type":"mcq","mods":["8"],"topic":"Radikulopatie C / L-S","stem":"51-letni pacjent zgłasza ból szyi promieniujący przez ramię i przedramię do palca środkowego lewej ręki, nasilający się przy próbie Spurlinga. W badaniu neurologicznym stwierdzono osłabienie wyprostu w lewym stawie łokciowym oraz wyraźnie osłabiony odruch z mięśnia trójgłowego ramienia. Który korzeń szyjny odpowiada za ten zespół?","opts":["Korzeń C5","Korzeń C6","Korzeń C7","Korzeń C8"],"keys":[2],"conf":"own","adapt":false,"gap":false,"src":"Sylabus PUM [8] · Ćw TK12 · Bóle barku i radikulopatia szyjna","why":"Najczęstsza radikulopatia szyjna dotyczy korzenia C7 (przepuklina C6–C7): ból i parestezje sięgają palca środkowego, osłabiony jest mięsień trójgłowy ramienia (prostowanie łokcia), a odruch z mięśnia trójgłowego ulega osłabieniu lub zniesieniu. Korzeń C6 unerwia kciuk/palec wskazujący i odruch z m. ramienno-promieniowego/dwugłowego, a C8 palec mały oraz mięśnie drobne ręki.","tip":"Zapamiętaj 7-kę w szyi: C7 = triceps + prostowanie łokcia + środkowy palec (najczęstsza radikulopatia szyjna).","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"bol-q7","at":"bole","type":"mcq","mods":["8"],"topic":"Zespół ogona końskiego","stem":"52-letni mężczyzna po dźwignięciu ciężaru odczuł gwałtowny ból krzyża promieniujący do obu pośladków. Po 8 godzinach pojawiło się znieczulenie okolicy krocza („spodenki jeździeckie”), zatrzymanie moczu mimo pełnego pęcherza oraz osłabienie zgięcia podeszwowego stóp. Które stwierdzenie opisuje prawidłową interpretację i postępowanie?","opts":["Należy zastosować leczenie zachowawcze NLPZ przez 4 tygodnie i dopiero przy braku poprawy wykonać MRI kręgosłupa","Jest to zespół ogona końskiego (uszkodzenie LMN) wymagający pilnego MRI kręgosłupa L-S i pilnej dekompresji neurochirurgicznej","W tym zespole charakterystyczne jest wygórowanie odruchów skokowych i obustronny objaw Babińskiego","Najczulszym objawem potwierdzającym ten zespół jest izolowany odwrócony objaw Lasègue’a (Mackiewicza) przy prawidłowej mikcji"],"keys":[1],"conf":"did","adapt":false,"gap":true,"src":"Sylabus PUM [8] · W03h / Sem TK11 · Zespół ogona końskiego","why":"Ból korzeniowy z zaburzeniami zwieraczy (retencja moczu) i znieczuleniem okolicy krocza w kształcie „spodenek jeździeckich” to obraz zespołu ogona końskiego (CES) — pilnego stanu neurochirurgicznego. Ponieważ w skład ogona końskiego wchodzą korzenie poniżej L1/L2, jest to uszkodzenie obwodowe (LMN): odruchy głębokie i odbytowy ulegają zniesieniu, a objaw Babińskiego nie występuje.","tip":"Każdy ból krzyża ze świeżymi zaburzeniami mikcji lub znieczuleniem krocza = natychmiastowe MRI L-S i pilny neurochirurg (<24–48 h).","zal":"W pytaniach testowych rozpoznanie ogona końskiego opiera się na klasycznej triadzie pełnoobjawowej: znieczulenie siodłowe, ostre zatrzymanie moczu/nietrzymanie stolca i niedowład wiotki kończyn.","akt":"Wytyczne NICE/BASS podkreślają pilne MRI już na etapie tzw. CES-suspected / incomplete (np. samo pogorszenie czucia krocza lub osłabienie strumienia moczu), zanim dojdzie do nieodwracalnego zatrzymania moczu z przepełnienia.","ans":"","reps":0,"bank":"modulowa"},{"id":"auto-q1","at":"autoimmuno","type":"mcq","mods":["9"],"topic":"Obraz SM i McDonald","stem":"28-letnia kobieta zgłasza ból prawej gałki ocznej nasilający się przy ruchach oraz spadek ostrości wzroku i wyblaknięcie barwy czerwonej od 4 dni; dno oka w oftalmoskopii jest prawidłowe, obecny względny dośrodkowy defekt źreniczny (RAPD). Dodatkowo w badaniu neurologicznym przy próbie spojrzenia w prawo prawe oko nie przywodzi, a w lewym (odwodzonym) występuje oczopląs poziomy, przy prawidłowej konwergencji. Jakie struktury uległy uszkodzeniu?","opts":["Prawy nerw wzrokowy (zapalenie wewnątrzgałkowe) oraz lewy nerw odwodzący (n. VI)","Prawy nerw wzrokowy (pozagałkowe zapalenie n. II) oraz prawy pęczek podłużny przyśrodkowy (MLF — międzyjądrowe porażenie spojrzenia, INO)","Skrzyżowanie nerwów wzrokowych oraz prawy nerw okoruchowy (n. III)","Lewa kora wzrokowa oraz oba jądra nerwów okoruchowych","Siatkówka oka prawego oraz móżdżek"],"keys":[1],"conf":"src","adapt":false,"gap":false,"src":"Sylabus PUM [9] · W03g · Sem TK02 · Podemski · Fuller","why":"Jednostronny spadek ostrości wzroku z bólem przy ruchach gałki ocznej, dyschromatopsją, RAPD i prawidłowym dnem oka („chory nic nie widzi, lekarz nic nie widzi”) to klasyczne pozagałkowe zapalenie nerwu wzrokowego (ON). Upośledzenie przywodzenia oka prawego przy zachowanej konwergencji i oczopląsie odwodzonego oka lewego stanowi międzyjądrowe porażenie spojrzenia (INO) wynikające z uszkodzenia prawego pęczka podłużnego przyśrodkowego (MLF) w pniu mózgu.","tip":"Połączenie pozagałkowego ON i INO (zwłaszcza obustronnego u młodego dorosłego) jest klasycznym zespołem wskazującym na stwardnienie rozsiane.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"auto-q2","at":"autoimmuno","type":"mcq","mods":["9"],"topic":"Obraz SM i McDonald","stem":"26-letnia pacjentka przebyła pierwszy w życiu epizod neurologiczny: podostre niedowidzenie oka lewego (pozagałkowe zapalenie nerwu wzrokowego). W wykonanym w 10. dobie MRI mózgu stwierdzono 3 ogniska hiperintensywne w T2/FLAIR (2 okołokomorowe ułożone prostopadle do komór bocznych oraz 1 podkorowe/juxtacortical), jednak żadne z ognisk nie ulega wzmocnieniu po podaniu gadolinu (Gd−). Badanie PMR wykazało 6 limfocytów/µl, prawidłowe stężenie białka oraz dodatnie prążki oligoklonalne (OCB IgG typu 2, nieobecne w surowicy). Która decyzja diagnostyczna wg kryteriów McDonalda (2017) jest prawidłowa?","opts":["Należy rozpoznać jedynie CIS i odroczyć rozpoznanie SM do pojawienia się drugiego rzutu klinicznego","Brak wzmocnienia po gadolinie wyklucza spełnienie kryteriów McDonalda, ponieważ w jednym MRI nie ma ognisk Gd+ i Gd−","Można rozpoznać pewne SM (RRMS): spełniono kryterium DIS (≥2/4 lokalizacji), a dodatnie prążki oligoklonalne w PMR zastępują kryterium DIT","Prążki oligoklonalne w PMR są kryterium diagnostycznym wyłącznie dla postaci pierwotnie postępującej (PPMS)","Konieczna jest biopsja mózgu w celu potwierdzenia demielinizacji"],"keys":[2],"conf":"src","adapt":false,"gap":true,"src":"Sylabus PUM [9] · W03g · Kryteria McDonalda 2017","why":"Wg kryteriów McDonalda z 2017 r. rozsianie w przestrzeni (DIS) wymaga ≥1 ogniska T2 w co najmniej 2 z 4 typowych okolic (okołokomorowa, korowa/podkorowa, podnamiotowa, rdzeń kręgowy) — pacjentka spełnia DIS (okołokomorowa + podkorowa). Gdy w pierwszym MRI wszystkie zmiany są Gd− (brak klasycznego DIT w obrazowaniu), obecność specyficznych dla PMR prążków oligoklonalnych IgG pozwala spełnić kryterium rozsiania w czasie (DIT) i rozpoznać SM już po pierwszym rzucie.","tip":"W kryteriach McDonalda 2017: DIS (≥2 z 4 okolic) + prążki oligoklonalne w PMR (typ 2 lub 3) = rozpoznanie SM bez czekania na kolejny rzut lub nowe ognisko w MRI.","zal":"W starszych pytaniach opartych na kryteriach McDonalda 2010 prążki oligoklonalne służyły głównie w rozpoznaniu PPMS, a w RRMS do DIT wymagano jednoczesnego ogniska Gd+ i Gd− lub nowego ogniska T2 w kolejnym MRI.","akt":"Kryteria McDonalda 2017 włączyły prążki oligoklonalne (OCB) jako pełnoprawny substytut DIT u chorych z CIS spełniających DIS; ponadto propozycje rewizji z 2024 r. dodają nerw wzrokowy jako 5. lokalizację DIS oraz biomarkery MRI (central vein sign, paramagnetic rim lesions).","ans":"","reps":0,"bank":"modulowa"},{"id":"auto-q3","at":"autoimmuno","type":"mcq","mods":["9"],"topic":"Rzut i DMT","stem":"33-letnia kobieta z rozpoznaną od 4 lat postacią rzutowo-remisyjną SM (EDSS 1,5) zgłasza się na dyżur z powodu gwałtownego pogorszenia ostrości wzroku w oku prawym oraz nasilenia drętwienia i osłabienia nóg utrzymującego się od 6 godzin. Dzień wcześniej wróciła z gorącej sauny, a dziś ma temperaturę 38,5°C, ból okolicy lędźwiowej i dyzurię. Jakie postępowanie jest najwłaściwsze w pierwszej kolejności?","opts":["Natychmiastowe włączenie metyloprednizolonu 1000 mg i.v. bez dodatkowych badań laboratoryjnych","Rozpoznanie pseudorzutu (zjawisko Uhthoffa nasilone gorączką w przebiegu infekcji) — pilne badanie ogólne i posiew moczu, leczenie przeciwgorączkowe oraz antybiotykoterapia ZUM przed ewentualną decyzją o steroidoterapii","Natychmiastowa plazmafereza (PLEX) z powodu ciężkiego rzutu pniowego","Zmiana terapii z interferonu beta na alemtuzumab w trybie ostrym na SOR","Rozpoznanie konwersji do postaci wtórnie postępującej (SPMS)"],"keys":[1],"conf":"did","adapt":false,"gap":false,"src":"Sylabus PUM [9] · Ćw TK05 · Podemski · Stępień","why":"Prawdziwy rzut SM definiuje się jako pojawienie się nowych lub wyraźne nasilenie wcześniejszych objawów neurologicznych trwające ≥24 godziny przy braku gorączki i aktywnego zakażenia. Wzrost temperatury ciała (gorączka w ZUM, gorąca kąpiel/sauna) przejściowo blokuje przewodnictwo w zdemielinizowanych aksonach (objaw Uhthoffa / pseudorzut). Należy wyleczyć infekcję i zbić gorączkę; podanie GKS przy nierozpoznanej infekcji może ją zaostrzyć.","tip":"Zawsze zanim rozpoznasz rzut SM i podasz metyloprednizolon: zapytaj o objawy infekcji (ZUM, przegrzanie) i sprawdź czas trwania objawów (≥24 h!).","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"auto-q4","at":"autoimmuno","type":"mcq","mods":["9"],"topic":"Rzut i DMT","stem":"37-letni mężczyzna z wysoko aktywnym RRMS leczony od 32 miesięcy natalizumabem (wcześniej przez 2 lata stosował immunosupresję, aktualny indeks przeciwciał anty-JCV w surowicy wynosi 2,4) rozwija w ciągu 3 tygodni postępującą niezborność prawej ręki, zaburzenia mowy i niedowidzenie połowicze, bez gorączki. W MRI mózgu widoczne jest rozległe, asymetryczne ognisko hiperintensywne w T2/FLAIR obejmujące istotę białą podkorową i włókna U lewej półkuli, bez efektu masy i bez wzmocnienia kontrastowego. Jakie jest najbardziej prawdopodobne rozpoznanie i postępowanie?","opts":["Klasyczny rzut SM — podwojenie dawki natalizumabu i 5 dni metyloprednizolonu i.v.","Postępująca wieloogniskowa leukoencefalopatia (PML) wywołana wirusem JC — natychmiastowe odstawienie natalizumabu, oznaczenie JCV-DNA (PCR) w PMR i rozważenie plazmaferezy (PLEX) z monitorowaniem w kierunku zespołu IRIS","Zakażenie wirusem opryszczki pospolitej (HSV-1) — acyklowir i kontynuacja natalizumabu","Obrzęk plamki związany z leczeniem — odstawienie leku i konsultacja okulistyczna","Wtórna autoimmunologiczna małopłytkowość polekowa"],"keys":[1],"conf":"inf","adapt":false,"gap":true,"src":"Sylabus PUM [9] · Sem TK02 · Wytyczne EAN/ECTRIMS","why":"Trzy główne czynniki ryzyka PML podczas leczenia natalizumabem to: wysokie miano przeciwciał anty-JCV, czas terapii >24 miesiące oraz wcześniejsza immunosupresja. Podostre objawy korowe/móżdżkowe z rozległą zmianą podkorową zajmującą włókna U bez efektu masy w MRI wymagają pilnego wykluczenia PML (PCR na JCV-DNA w PMR) i natychmiastowego przerwania podawania natalizumabu.","tip":"Zapamiętaj powikłania flagowych leków DMT: natalizumab → PML (JCV); fingolimod → bradykardia/blok AV (monitoring EKG 6 h po 1. dawce) i obrzęk plamki; teryflunomid → silna teratogenność (wymywanie cholestyraminą); alemtuzumab → wtórne choroby autoimmunologiczne.","zal":"W klasycznych schematach „eskalacyjnych” terapię rozpoczynano niemal zawsze od leków umiarkowanej skuteczności (IFN-β, octan glatirameru), a leki o wysokiej skuteczności (natalizumab, anty-CD20) włączano dopiero po niepowodzeniu leczenia.","akt":"Aktualne wytyczne EAN/ECTRIMS zalecają wczesne stosowanie terapii o wysokiej skuteczności (HET: okrelizumab, ofatumumab, natalizumab, kladrybina) od początku choroby u pacjentów z czynnikami złego rokowania lub wysoką aktywnością zapalną („flip the pyramid”).","ans":"","reps":0,"bank":"modulowa"},{"id":"auto-q5","at":"autoimmuno","type":"mcq","mods":["9"],"topic":"NMOSD i MOGAD","stem":"31-letnia kobieta przebyła 3 tygodnie temu epizod uporczywej czkawki i niepowstrzymanych wymiotów trwający 9 dni (gastroskopia i diagnostyka gastrologiczna prawidłowe). Obecnie wystąpiło ciężkie obustronne pogorszenie ostrości wzroku oraz niedowład kończyn dolnych z zaburzeniami zwieraczy. W MRI rdzenia szyjno-piersiowego stwierdza się ciągłą zmianę hiperintensywną T2 zajmującą centralnie rdzeń na długości od C2 do C7 (6 segmentów kręgowych). W PMR brak prążków oligoklonalnych. Które stwierdzenie jest prawdziwe?","opts":["Obraz jest typowy dla SM — należy pilnie włączyć interferon beta-1a w wysokiej dawce","Obraz odpowiada spektrum NMOSD (area postrema syndrome + obustronne ON + LETM ≥3 segmenty); należy oznaczyć AQP4-IgG, pilnie wdrożyć metyloprednizolon i.v. z wczesną plazmaferezą oraz bezwzględnie unikać interferonu beta, fingolimodu i natalizumabu","Zmiana ≥3 segmentów w rdzeniu wyklucza chorobę demielinizacyjną i dowodzi guza śródrdzeniowego","Rozstrzygające dla rozpoznania jest podanie próbne glikokortykosteroidów doustnych w małej dawce przez 2 miesiące","W przypadku AQP4-IgG+ najlepszym leczeniem podtrzymującym jest fumaran dimetylu"],"keys":[1],"conf":"src","adapt":false,"gap":false,"src":"Sylabus PUM [9] · W03g · Kryteria IPND NMOSD","why":"Zespół pola najdalszego (area postrema — czkawka/nudności/wymioty), ciężkie obustronne zapalenie nerwów wzrokowych oraz podłużnie rozległe poprzeczne zapalenie rdzenia (LETM ≥3 segmenty kręgowe w osi długiej, centralne w przekroju) przy braku OCB to klasyczny obraz NMOSD (związanego z przeciwciałami AQP4-IgG skierowanymi przeciwko kanałom wodnym na stopkach astrocytów). Leki stosowane w SM (IFN-β, fingolimod, natalizumab, alemtuzumab) mogą wywołać ciężkie zaostrzenie NMOSD!","tip":"Czkawka/wymioty + ciężkie ON + LETM ≥3 segmenty = NMOSD (AQP4-IgG). W rzucie szybko GKS i.v. + PLEX, a NIGDY interferon beta ani fingolimod!","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"auto-q6","at":"autoimmuno","type":"mcq","mods":["9"],"topic":"NMOSD i MOGAD","stem":"21-letni mężczyzna 10 dni po infekcji dróg oddechowych rozwinął obustronne pogorszenie wzroku z wyraźnym obrzękiem obu tarcz nerwu wzrokowego w badaniu dna oka oraz parestezje krocza i zatrzymanie moczu. W MRI oczodołów widoczne obustronne wzmocnienie przednich odcinków i pochewek nerwów wzrokowych, a w MRI rdzenia zmiana LETM obejmująca stożek rdzeniowy. Przeciwciała AQP4-IgG oraz prążki oligoklonalne w PMR są ujemne, natomiast w teście komórkowym (CBA) stwierdzono wysokie miano MOG-IgG. Która cecha najlepiej charakteryzuje MOGAD w porównaniu z AQP4+ NMOSD?","opts":["Zawsze postępujący przebieg wtórny bez odpowiedzi na glikokortykosteroidy","Wyraźna przewaga kobiet (~9:1) oraz stała obecność prążków oligoklonalnych w PMR (>90%)","Częste zajęcie przedniego odcinka nerwu wzrokowego z obrzękiem tarczy n. II i stożka rdzeniowego (lub zespół ADEM-podobny), porównywalna częstość u obu płci oraz zwykle bardzo dobra odpowiedź na GKS i lepsze rokowanie funkcjonalne","Pierwotna astrocytopatia z martwicą astrocytów w miejscu skrzyżowania wzrokowego","Konieczność natychmiastowego włączenia interferonu beta jako leku I rzutu"],"keys":[2],"conf":"inf","adapt":false,"gap":true,"src":"Sylabus PUM [9] · Kryteria MOGAD 2023 · Stępień","why":"MOGAD (choroba związana z przeciwciałami przeciwko glikoproteinie mieliny oligodendrocytów) dotyczy w równym stopniu kobiet i mężczyzn (często dzieci i młodych dorosłych), klasycznie wywołuje obustronne zapalenie przedniego odcinka nerwów wzrokowych z obrzękiem tarczy (papillitis) i wzmocnieniem pochewki (perineuritis), zapalenie stożka rdzeniowego lub ADEM. W odróżnieniu od AQP4+ NMOSD odpowiedź na wysokie dawki GKS bywa szybka, a utrwalone kalectwo rzadsze (choć choroba może nawracać po zbyt szybkim odstawieniu steroidów).","tip":"Porównaj 3 lokalizacje nerwu wzrokowego: SM = krótkie jednostronne pozagałkowe (dno oka OK); NMOSD (AQP4) = długie tylne aż do skrzyżowania; MOGAD = obustronne przednie z obrzękiem tarczy i pochewki + stożek rdzeniowy!","zal":"W starszych opracowaniach przypadki z zapaleniem nerwów wzrokowych i LETM przy ujemnych AQP4-IgG określano zbiorczo jako „seronegatywne NMO (choroba Devica)” bez odrębnego podtypu.","akt":"Międzynarodowe kryteria z 2023 r. wyodrębniają MOGAD jako odrębną jednostkę chorobową (typowy zespół kliniczny + dodatni wynik MOG-IgG w teście CBA), wymagającą powolnej redukcji GKS i odrębnych strategii zapobiegania nawrotom (np. podtrzymujące IVIG, azatiopryna, MMF lub tocilizumab; skuteczność anty-CD20 bywa niższa niż w AQP4+ NMOSD).","ans":"","reps":0,"bank":"modulowa"},{"id":"auto-q7","at":"autoimmuno","type":"mcq","mods":["9"],"topic":"Zapalenia autoimmun.","stem":"23-letnia studentka została przyjęta na oddział psychiatryczny z powodu nagłej bezsenności, urojeń i pobudzenia psychoruchowego po przebytym 2 tygodnie wcześniej stanie podgorączkowym. W 5. dobie dołączyły się napady drgawkowe, rytmiczne dyskinezy ustno-twarzowe (mlaskanie, wykrzywianie warg), wahania ciśnienia tętniczego, tachykardia oraz zaburzenia świadomości. MRI mózgu nie wykazało ognisk, PCR PMR w kierunku HSV-1/2 jest ujemne, pleocytoza wynosi 28 limfocytów/µl, a w EEG opisano wzorzec „extreme delta brush”. Które postępowanie jest kluczowe?","opts":["Zwiększenie dawek neuroleptyków i wyłączna obserwacja psychiatryczna przez 4 tygodnie","Oznaczenie przeciwciał anty-NMDAR w PMR (i surowicy), pilna diagnostyka obrazowa w kierunku potworniaka jajnika (USG/TK/MRI miednicy) oraz natychmiastowe włączenie immunoterapii I rzutu (metyloprednizolon i.v. + IVIG lub plazmafereza)","Rozpoznanie zapalenia anty-LGI1 i poszukiwanie drobnokomórkowego raka płuca jako najczęstszej przyczyny u 23-latki","Włączenie cyklofosfamidu w monoterapii bez steroidów i oczekiwanie na wynik biopsji mózgu","Rozpoznanie stwardnienia rozsianego postaci piorunującej (Marburga) i podanie interferonu beta"],"keys":[1],"conf":"src","adapt":false,"gap":false,"src":"Sylabus PUM [9] · W03g · Kryteria Grausa AE","why":"Obraz odpowiada autoimmunologicznemu zapaleniu mózgu z przeciwciałami przeciwko receptorowi NMDA (anty-NMDAR): charakterystyczny przebieg fazowy (prodrom → ostra psychoza/katatonia → napady → dyskinezy ustno-twarzowe, dysautonomia i hipowentylacja), częsty prawidłowy obraz MRI (~50%), wzorzec EEG „extreme delta brush” oraz silne powiązanie z potworniakiem jajnika (~40–50% u młodych kobiet). Przeciwciała anty-NMDAR są czulsze w PMR niż w surowicy, a po wykluczeniu infekcji (HSV) niezwłocznie wdraża się GKS i.v. + IVIG/PLEX i usuwa guz.","tip":"Zapamiętaj duet AE na egzamin: młoda kobieta + psychoza + dyskinezy ustno-twarzowe + dysautonomia = anty-NMDAR (szukaj potworniaka jajnika!). Starszy chory + napady dystoniczne twarzowo-ramienne (FBDS) + hiponatremia = anty-LGI1.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"obw-q1","at":"obwodowy","type":"mcq","mods":["10"],"topic":"Polineuropatie i mononeuropatie","stem":"58-letni mężczyzna po zabiegu endoprotezoplastyki prawego stawu kolanowego budzi się z opadaniem prawej stopy. W badaniu stwierdza się znaczne osłabienie zgięcia grzbietowego i nawracania (ewersji) prawej stopy oraz zaburzenia czucia na grzbiecie stopy i bocznej powierzchni podudzia. Siła odwracania (inwersji) stopy i odwodzenia prawego biodra jest prawidłowa, objaw Lasègue’a ujemny, a odruchy kolanowy i skokowy są zachowane. Która struktura uległa uszkodzeniu?","opts":["korzeń nerwowy L5 po stronie prawej","nerw strzałkowy wspólny w okolicy główki strzałki","nerw piszczelowy w dole podkolanowym","korzeń nerwowy S1 po stronie prawej","nerw udowy po stronie prawej"],"keys":[1],"conf":"did","adapt":false,"gap":false,"src":"Sylabus PUM [10] · Ćw TK10 · Topodiagnostyka obwodowa","why":"Nerw strzałkowy wspólny (często uciskany na główce strzałki) zaopatruje prostowniki stopy i palucha oraz mięśnie strzałkowe (ewersja stopy). Natomiast mięsień piszczelowy tylny (inwersja stopy) i pośladkowy średni (odwodzenie biodra) otrzymują unerwienie z korzenia L5 innymi nerwami (piszczelowym i pośladkowym górnym), dlatego ich pełna sprawność wyklucza radikulopatię L5.","tip":"Test różnicowy opadania stopy przy łóżku: zbadaj inwersję (odwracanie) stopy. Prawidłowa inwersja = nerw strzałkowy; osłabiona inwersja + ból krzyża = korzeń L5.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"obw-q2","at":"obwodowy","type":"mcq","mods":["10"],"topic":"Polineuropatie i mononeuropatie","stem":"64-letnia chora z 18-letnim wywiadem cukrzycy typu 2 skarży się na symetryczne drętwienie, mrowienie i palenie stóp o układzie „skarpetek”, osłabienie czucia wibracji 128 Hz na kostkach oraz obustronnie zniesione odruchy skokowe. W badaniu elektroneurograficznym (ENG) stwierdzono wyraźne obniżenie amplitudy potencjałów CMAP i SNAP przy prawidłowych lub granicznie zwolnionych szybkościach przewodzenia. Jaki typ uszkodzenia odpowiada temu obrazowi?","opts":["ostra zapalna poliradikuloneuropatia demielinizacyjna (AIDP)","dystalna symetryczna polineuropatia aksonalna","przewlekła zapalna polineuropatia demielinizacyjna (CIDP)","dziedziczna polineuropatia demielinizacyjna typu CMT1A"],"keys":[1],"conf":"inf","adapt":false,"gap":true,"src":"Sylabus PUM [10] · Sem TK03 · Podemski / Stępień","why":"Zanik amplitud odpowiedzi ruchowych (CMAP) i czuciowych (SNAP) przy prawidłowej bądź nieznacznie obniżonej szybkości przewodzenia (NCV) w dystalnym rozkładzie zależnym od długości aksonu („skarpetki i rękawiczki”) jest klasycznym wzorcem polineuropatii aksonalnej — typowej m.in. dla cukrzycy, alkoholu oraz niedoboru witaminy B12. W neuropatiach demielinizacyjnych (AIDP, CIDP, CMT1A) dominuje znaczne zwolnienie NCV, wydłużenie latencji fali F i blok przewodzenia.","tip":"Reguła ENG: Aksonalna = spadek AMPLITUDY (CMAP/SNAP); Demielinizacyjna = spadek SZYBKOŚCI przewodzenia (NCV), wydłużenie latencji i blok przewodzenia.","zal":"W pytaniach testowych polineuropatię cukrzycową klasyfikuje się jako typową dystalną symetryczną polineuropatię aksonalną zależną od długości nerwów.","akt":"W praktyce klinicznej (EAN/AAN) nawet u chorego na cukrzycę przed ostatecznym przypisaniem objawów wyłącznie cukrzycy należy wykonać panel przesiewowy przyczyn odwracalnych: stężenie witaminy B12, TSH oraz elektroforezę białek surowicy z immunofiksacją (wykluczenie gammapatii monoklonalnej).","ans":"","reps":0,"bank":"modulowa"},{"id":"obw-q3","at":"obwodowy","type":"mcq","mods":["10"],"topic":"GBS i CIDP","stem":"32-letni mężczyzna trafia na SOR z powodu szybko narastającego od 4 dni symetrycznego osłabienia kończyn dolnych, które w ostatniej dobie objęło ręce i mięśnie mimiczne twarzy. Dwa tygodnie wcześniej przebył ostrą biegunkę bakteryjną. W badaniu: wiotki niedowład czterokończynowy, zniesione wszystkie odruchy głębokie, niewielkie parestezje dystalne bez wyraźnego poziomu czucia. W PMR pobranym w 9. dobie: białko 192 mg/dl, cytoza 3 komórki/µl. Które postępowanie jest właściwe?","opts":["natychmiastowe włączenie dożylnego metyloprednizolonu 1000 mg/d przez 5 dni","podanie dożylnych immunoglobulin (IVIG) lub wykonanie plazmaferezy (PLEX) z monitorowaniem wydolności oddechowej (FVC) i EKG","rozpoczęcie doustnej pirydostygminy 60 mg co 4 godziny","podanie acyklowiru i ceftriaksonu do czasu wykluczenia zapalenia mózgu","wypisanie pacjenta z zaleceniem planowego EMG za 6 tygodni"],"keys":[1],"conf":"src","adapt":false,"gap":true,"src":"Sylabus PUM [10] · W03h / Sem TK08 · Wytyczne EAN/PNS 2023","why":"Postępujący wstępujący wiotki niedowład z arefleksją po infekcji (klasycznie Campylobacter jejuni) oraz rozszczepieniem białkowo-komórkowym w PMR (wysokie białko przy prawidłowej cytozie) to typowy obraz zespołu Guillaina-Barrégo (GBS). Jedynym skutecznym leczeniem przyczynowym o równoważnej skuteczności są IVIG lub plazmafereza (PLEX), przy ścisłym monitorowaniu pojemności życiowej (FVC) i zaburzeń autonomicznych. Glikokortykosteroidy w GBS NIE działają.","tip":"Złota zasada GBS: IVIG lub plazmafereza TAK, glikokortykosteroidy NIE! Pilnuj FVC (<20 ml/kg lub „zasada 20/30/40”) i EKG z powodu ryzyka nagłej niewydolności oddechowej i dysautonomii.","zal":"Klasyczny opis podręcznikowy podkreśla obecność rozszczepienia białkowo-komórkowego w PMR (podwyższone białko, prawidłowa liczba komórek) od ok. 2. tygodnia choroby oraz zakaz stosowania steroidów.","akt":"Wytyczne EAN/PNS 2023 zwracają uwagę, że w 1. tygodniu objawów białko w PMR jest prawidłowe u 30–50% chorych z GBS — prawidłowy wynik wczesnego nakłucia nie wyklucza rozpoznania i nie może opóźniać włączenia IVIG/PLEX. Wariant ruchowy AMAN po C. jejuni często wiąże się z przeciwciałami anty-GM1/GD1a, a zespół Millera-Fishera z anty-GQ1b.","ans":"","reps":0,"bank":"modulowa"},{"id":"obw-q4","at":"obwodowy","type":"mcq","mods":["10"],"topic":"GBS i CIDP","stem":"56-letnia kobieta od 3 miesięcy obserwuje stopniowo narastający, symetryczny niedowład mięśni proksymalnych (trudność ze wstawaniem z krzesła i unoszeniem rąk) i dystalnych kończyn wraz z mrowieniem stóp oraz uogólnionym zniesieniem odruchów głębokich. W badaniu ENG stwierdzono wyraźne zwolnienie szybkości przewodzenia, wydłużenie latencji fali F oraz częściowy blok przewodzenia, a w PMR białko wynosi 135 mg/dl przy 2 limfocytach/µl. Które rozpoznanie i postępowanie jest prawidłowe?","opts":["zespół Guillaina-Barrégo — glikokortykosteroidy są przeciwwskazane","przewlekła zapalna poliradikuloneuropatia demielinizacyjna (CIDP) — leczeniem I rzutu są glikokortykosteroidy, IVIG lub plazmafereza","stwardnienie zanikowe boczne (SLA) — należy włączyć ryluzol","dystrofia mięśniowa obręczowo-kończynowa — rozpoznanie stawia się bez ENG na podstawie samej biopsji mięśnia"],"keys":[1],"conf":"src","adapt":false,"gap":false,"src":"Sylabus PUM [10] · Sem TK08 · EAN/PNS CIDP 2021","why":"Progresja lub nawrotowy przebieg niedowładu symetrycznego (zajmującego zarówno mięśnie proksymalne, jak i dystalne) trwający powyżej 8 tygodni (>2 miesiące) z arefleksją, demielinizacją w ENG oraz rozszczepieniem białkowo-komórkowym w PMR rozpoznaje się jako CIDP. W przeciwieństwie do GBS glikokortykosteroidy są w CIDP jedną z podstawowych, bardzo skutecznych metod leczenia pierwszego rzutu (obok IVIG i plazmaferezy).","tip":"GBS <4 tygodnie (GKS nieskuteczne!) vs CIDP >8 tygodni (GKS skuteczne jako lek I rzutu obok IVIG/PLEX).","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"obw-q5","at":"obwodowy","type":"mcq","mods":["11"],"topic":"Miastenia, LEMS i przełomy","stem":"29-letnia kobieta z rozpoznaną miastenią gravis (przeciwciała anty-AChR dodatnie, po tymektomii) zgłasza się na SOR w przebiegu zakażenia układu moczowego leczonego od 2 dni gentamycyną i cyprofloksacyną. Rozwinęła szybko narastającą dyzartrię nosową, dysfagię, nasiloną duszność, tachykardię, zlewne poty i lęk; źrenice są szerokie, po 5 mm, odruchy głębokie prawidłowe, a pacjentka nie jest w stanie policzyć na jednym wydechu do 12. Które postępowanie jest najwłaściwsze?","opts":["natychmiastowe zwiększenie dawki doustnej pirydostygminy i dołączenie siarczanu magnezu i.v.","rozpoznanie przełomu cholinergicznego i podanie dużej dawki atropiny bez zabezpieczania dróg oddechowych","rozpoznanie przełomu miastenicznego: pilne zabezpieczenie dróg oddechowych (intubacja/OIT), odstawienie antybiotyków nasilających blok NM, czasowe wstrzymanie pirydostygminy oraz włączenie IVIG lub plazmaferezy","wykonanie punkcji lędźwiowej i podanie dożylnego metyloprednizolonu w dawce 1 g bez wspomagania oddechu"],"keys":[2],"conf":"did","adapt":false,"gap":true,"src":"Sylabus PUM [11] · Sem TK09 / Ćw TK11 · MGFA / EAN","why":"Infekcja oraz leki blokujące złącze nerwowo-mięśniowe (aminoglikozydy — gentamycyna, fluorochinolony — cyprofloksacyna) wywołały przełom miasteniczny z zagrażającą niewydolnością oddechową (liczenie na wydechu <20). W przeciwieństwie do przełomu cholinergicznego nie ma tu zwężenia źrenic ani objawów SLUDGE. Priorytetem jest wczesna intubacja na OIT, czasowe wstrzymanie inhibitorów AChE (by nie nasilać wydzieliny w drogach oddechowych), leczenie przyczynowe IVIG lub PLEX oraz zmiana antybiotyku na bezpieczny w MG. Magnez i.v. jest w MG bezwzględnie przeciwwskazany!","tip":"Przełom miasteniczny = szerokie źrenice + duszność + wyzwalacz (infekcja / aminoglikozyd / fluorochinolon / Mg²⁺). Przełom cholinergiczny = wąskie źrenice (mioza) + ślinotok/biegunka/fascykulacje (SLUDGE).","zal":"Klasycznie przełom miasteniczny i cholinergiczny różnicowano próbą z edrofonium (Tensilon), a w leczeniu MG podkreślano zestaw: pirydostygmina, prednizon, azatiopryna i tymektomia przy grasiczaku.","akt":"Próba z edrofonium nie jest dziś rutynowo stosowana (ryzyko zatrzymania krążenia i zaostrzenia bloku); przy każdej zagrażającej niewydolności oddechowej w MG najpierw zabezpiecza się drogi oddechowe i podaje IVIG lub PLEX. Dodatkowo w uogólnionej MG anty-AChR bez grasiczaka tymektomia poprawia rokowanie (MGTX), w MG anty-MuSK lekiem z wyboru bywa rytuksymab, a w opornej MG stosuje się blokery FcRn (efgartigimod) i inhibitory C5.","ans":"","reps":0,"bank":"modulowa"},{"id":"obw-q6","at":"obwodowy","type":"mcq","mods":["11"],"topic":"Miastenia, LEMS i przełomy","stem":"63-letni wieloletni palacz papierosów zgłasza się z powodu postępującego od kilku miesięcy osłabienia mięśni ud i obręczy biodrowej (trudność przy wstawaniu z krzesła i wchodzeniu po schodach) oraz dokuczliwej suchości w jamie ustnej i zaparć. W badaniu stwierdza się niedowład proksymalny kończyn dolnych bez ptozy i bez zaburzeń czucia oraz zniesione odruchy kolanowe i skokowe, które jednak wyraźnie pojawiają się po 10 sekundach maksymalnego skurczu mięśnia czworogłowego. Które rozpoznanie i wynik badań są najbardziej prawdopodobne?","opts":["miastenia gravis z grasiczakiem — dekrement >10% w stymulacji 3 Hz oraz przeciwciała anty-AChR","zespół miasteniczny Lamberta-Eatona (LEMS) — przeciwciała anty-VGCC, inkrement CMAP >60–100% przy stymulacji wysoką częstotliwością (20–50 Hz) oraz konieczność pilnego TK klatki piersiowej w kierunku raka drobnokomórkowego płuca (SCLC)","zatrucie jadem kiełbasianym (botulizm) — wąskie źrenice i zstępujące porażenie gałek ocznych","zapalenie skórno-mięśniowe — prawidłowe odruchy głębokie i brak zmian w stymulacji nerwów"],"keys":[1],"conf":"src","adapt":false,"gap":false,"src":"Sylabus PUM [11] · Sem TK09 · Podemski / Stępień","why":"Osłabienie proksymalne głównie kończyn dolnych, objawy dysautonomii (suchość w ustach, zaparcia), arefleksja poprawiająca się po krótkim wysiłku (fenomen rozgrzewki / torowania powysiłkowego) u palacza to klasyczny obraz zespołu Lamberta-Eatona (LEMS). Autoprzeciwciała przeciw presynaptycznym kanałom wapniowym (anty-VGCC) upośledzają uwalnianie ACh, dając niską wyjściową amplitudę CMAP i wyraźny inkrement (>60–100%) przy stymulacji 20–50 Hz. U >50% chorych LEMS jest zespołem paraneoplastycznym związanym z SCLC.","tip":"LEMS = kanały presynaptyczne VGCC + SCLC u palacza + suchość w ustach + poprawa po wysiłku (inkrement w EMG). Miastenia = receptory postsynaptyczne AChR/MuSK + grasiczak + pogorszenie po wysiłku (dekrement 3 Hz).","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"obw-q7","at":"obwodowy","type":"mcq","mods":["11"],"topic":"Miopatie i EMG","stem":"49-letnia pacjentka od 2 miesięcy ma trudności z podnoszeniem się z niskiego krzesła, wchodzeniem po schodach i czesaniem włosów, przy pełnej sile uścisku dłoni. Na grzbietach stawów śródręczno-paliczkowych widoczne są sino-czerwone grudki, a wokół oczu fioletowawy rumień. Czucie powierzchowne i głębokie oraz odruchy głębokie są prawidłowe, a aktywność kinazy kreatynowej (CK) wynosi 4600 U/l. Jakiego zapisu spodziewasz się w badaniu EMG igłowym i jakie jest dalsze kluczowe działanie?","opts":["potencjałów jednostek ruchowych (MUP) o dużej amplitudzie i wydłużonym czasie trwania z ubogą rekrutacją; włączenie dożylnego magnezu","potencjałów MUP o niskiej amplitudzie, krótkim czasie trwania i polifazowych z przedwczesną rekrutacją; rozpoznanie zapalenia skórno-mięśniowego, włączenie GKS i pilny skrining onkologiczny","prawidłowego zapisu EMG igłowego przy wybitnym dekrementem 3 Hz w próbie stymulacyjnej","zwolnienia szybkości przewodzenia nerwowego (NCV <25 m/s) i wydłużenia latencji fali F bez podwyższenia CK"],"keys":[1],"conf":"own","adapt":false,"gap":false,"src":"Sylabus PUM [11] · Sem TK09 / Ćw TK11 · Podemski / Stępień","why":"Symetryczne osłabienie proksymalne bez zaburzeń czucia i z zachowanymi odruchami oraz wysokim stężeniem CK wskazuje na miopatię pierwotną — tu zapalenie skórno-mięśniowe (grudki Gottrona + rumień heliotropowy). Zapis miogenny w EMG igłowym cechuje się małymi, krótkimi, polifazowymi potencjałami MUP oraz przedwczesną (nadmierną) rekrutacją. U dorosłych z zapaleniem skórno-mięśniowym obowiązkowy jest szeroki skrining w kierunku nowotworu złośliwego.","tip":"Zapis MIOGENNY = potencjały Niskie, Krótkie, Polifazowe + Wczesna rekrutacja (przeciwieństwo zapisu NEUROGENNEGO: Wysokie, Szerokie MUP + Uboga rekrutacja). Przy DM u dorosłych zawsze szukaj nowotworu, a u chorego >50 r.ż. opornego na GKS z zajęciem zginaczy palców pamiętaj o IBM!","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"guzy-q1","at":"guzy","type":"mcq","mods":["13"],"topic":"Lokalizacja i ICP","stem":"57-letni mężczyzna zgłasza się z powodu pierwszego w życiu uogólnionego napadu padaczkowego oraz narastającego od 4 tygodni porannego bólu głowy nasilającego się przy kaszlu i pochylaniu. W badaniu dna oka stwierdzono obustronny obrzęk tarcz nerwów wzrokowych (tarczę zastoinową). Które działanie jest w tym momencie BEZWZGLĘDNIE PRZECIWWSKAZANE?","opts":["Wykonanie pilnego badania MRI mózgu przed i po podaniu gadolinu (lub TK głowy w trybie dyżurowym)","Natychmiastowe wykonanie diagnostycznego nakłucia lędźwiowego (LP) przed badaniami obrazowymi","Włączenie leku przeciwpadaczkowego bez indukcji CYP450 (np. lewetyracetamu) po pierwszym napadzie objawowym","Zastosowanie deksametazonu w przypadku uwidocznienia guza z rozległym obrzękiem naczyniopochodnym","Zebranie wywiadu onkologicznego i ocena pod kątem ogniska pierwotnego (m.in. RTG/TK klatki piersiowej)"],"keys":[1],"conf":"src","adapt":false,"gap":false,"src":"Sylabus PUM · Sem TK05, Ćw TK09 / Podemski, Fuller","why":"Obecność tarczy zastoinowej, porannych bólów głowy nasilanych kaszlem (wzrost ICP) oraz pierwszego napadu padaczkowego po 40. r.ż. nakazuje podejrzenie guza mózgu z efektem masy. Nakłucie lędźwiowe przed wykluczeniem ciasnoty wewnątrzczaszkowej grozi gwałtownym wgłobieniem migdałków móżdżku w otwór wielki i zgonem.","tip":"Złota reguła PUM: tarcza zastoinowa lub objawy ogniskowe = ZAKAZ nakłucia lędźwiowego do czasu wykluczenia guza i efektu masy w TK/MRI.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"guzy-q2","at":"guzy","type":"mcq","mods":["13"],"topic":"Objawy ogniskowe","stem":"46-letnia pacjentka skarży się na narastające od kilku miesięcy zawężenie bocznych pól widzenia („potrącanie futryn po obu stronach”), poranne bóle głowy, mlekotok oraz wtórny brak miesiączki. W badaniu perymetrycznym stwierdzono niedowidzenie połowicze dwuskroniowe (hemianopsję bitemporalną). Które rozpoznanie i postępowanie jest najbardziej trafne?","opts":["Oponiak rynienki węchowej uciskający nerwy węchowe (zespół Foster-Kennedy’ego)","Makrogruczolak przysadki uciskający skrzyżowanie wzrokowe od dołu; w przypadku prolaktynomy leczeniem z wyboru są agoniści dopaminy (np. kabergolina)","Glejak płata potylicznego powodujący jednoimienne niedowidzenie z zaoszczędzeniem plamki","Nerwiak nerwu VIII zajmujący kąt mostowo-móżdżkowy i nerw trójdzielny","Przerzut do płata skroniowego uszkadzający pętlę Meyera (kwadrantopsja górna jednoimienna)"],"keys":[1],"conf":"src","adapt":false,"gap":false,"src":"Sylabus PUM · TK05 / Stępień, Kozubski","why":"Ucisk skrzyżowania wzrokowego (chiasma opticum) przez rozrastający się ku górze gruczolak przysadki uszkadza skrzyżowane włókna z nosowych połów siatkówek, co daje heteronimiczną hemianopsję dwuskroniową (często zaczynającą się od górnych kwadrantów). Współistnienie mlekotoku i braku miesiączki wskazuje na guz prolaktynowy (prolactinoma) — jedyny gruczolak przysadki leczony standardowo farmakologicznie agonistami dopaminy.","tip":"Zapamiętaj parę: skrzyżowanie wzrokowe = hemianopsja dwuskroniowa (różnoimienna); pasmo wzrokowe / promienistość / kora potyliczna = hemianopsja jednoimienna.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"guzy-q3","at":"guzy","type":"mcq","mods":["13"],"topic":"Objawy ogniskowe","stem":"54-letni mężczyzna zgłasza się z powodu postępującego od 2 lat jednostronnego niedosłuchu odbiorczego i szumów usznych w uchu prawym. W badaniu neurologicznym stwierdza się ponadto osłabienie prawego odruchu rogówkowego, dyskretną asymetrię twarzy oraz łagodną ataksję prawej ręki. Gdzie zlokalizowany jest guz i jaki jest najczęstszy typ histologiczny w tym miejscu?","opts":["Szczelina oczodołowa górna — oponiak skrzydła kości klinowej (nn. III, IV, VI, V1)","Prawy kąt mostowo-móżdżkowy — osłoniak przedsionkowy (nerwiak nerwu VIII)","Okolica szyszynki — rozrodczak z zespołem Parinauda (porażenie spojrzenia w górę)","Zatoka jamista — gruczolak przysadki z porażeniem nerwów gałkoruchowych","Płat skroniowy prawy — glejak wielopostaciowy z napadami hakowymi"],"keys":[1],"conf":"src","adapt":false,"gap":false,"src":"Sylabus PUM · Ćw TK09 / Fuller, Podemski","why":"Klasyczna sekwencja objawów guza kąta mostowo-móżdżkowego (CPA) zaczyna się od uszkodzenia n. VIII (jednostronny niedosłuch odbiorczy, szumy uszne, zaburzenia równowagi), następnie dołącza n. V (wczesne zniesienie lub osłabienie odruchu rogówkowego), n. VII (obwodowy niedowład twarzy) oraz półkula móżdżku (ataksja tożstronna). Najczęstszym guzem CPA jest osłoniak przedsionkowy (schwannoma n. VIII), przed oponiakiem i perlakiem.","tip":"Jednostronny odbiorczy niedosłuch + brak odruchu rogówkowego = pilne MRI mózgu z gadolinem pod kątem kąta mostowo-móżdżkowego.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"guzy-q4","at":"guzy","type":"mcq","mods":["13"],"topic":"Typy guzów i MRI","stem":"U 64-letniego chorego z szybko narastającym niedowładem lewostronnym i apatią MRI mózgu (T1+Gd) uwidoczniło rozległą masę w prawym płacie czołowym przechodzącą przez ciało modzelowate na stronę przeciwną („guz motylkowy”), z nieregularnym wzmocnieniem obrączkowatym i centralną strefą martwicy. Które stwierdzenie dotyczące epidemiologii i rozpoznania jest PRAWIDŁOWE?","opts":["Najczęstszymi guzami wewnątrzczaszkowymi u dorosłych ogółem są oponiaki, a przedstawiony obraz odpowiada oponiakowi z ogonem oponowym","Najczęstszymi guzami wewnątrzczaszkowymi u dorosłych ogółem są przerzuty, natomiast przedstawiony obraz jest klasyczny dla glejaka wielopostaciowego (glioblastoma IDH-wildtype, WHO 4) — najczęstszego pierwotnego złośliwego guza mózgu","Obraz wzmocnienia obrączkowatego z martwicą wyklucza glejaka i jednoznacznie dowodzi ropnia bakteryjnego","Rozpoznanie glioblastoma wymaga obecności mutacji IDH1 oraz kodelecji 1p/19q"],"keys":[1],"conf":"inf","adapt":false,"gap":true,"src":"Sylabus PUM · Sem TK05 / WHO CNS5 (2021) / EANO","why":"W praktyce klinicznej dorosłych najczęstszymi guzami OUN ogółem są przerzuty (ok. 50% guzów wewnątrzczaszkowych — głównie z płuca, piersi, czerniaka, nerki i jelita grubego). Wśród guzów pierwotnych złośliwych dominuje glejak wielopostaciowy (GBM, WHO 4), dający typowo naciek przez ciało modzelowate, centralną martwicę, nieregularne wzmocnienie obrączkowate i duży obrzęk.","tip":"W pytaniach testowych rozróżniaj: najczęstszy guz OUN dorosłych ogółem = przerzut; najczęstszy pierwotny łagodny = oponiak; najczęstszy pierwotny złośliwy = glejak wielopostaciowy (GBM).","zal":"W starszych materiałach bywa skrót „najczęstszy guz mózgu u dorosłych = glejak” oraz podział GBM na postać IDH-dziką i IDH-zmutowaną (WHO 2016).","akt":"Według klasyfikacji WHO CNS5 (2021) termin „glioblastoma” (WHO 4) jest zastrzeżony wyłącznie dla glejaków IDH-wildtype (guzy z mutacją IDH klasyfikuje się osobno jako astrocytoma IDH-mutant stopnia 2–4).","ans":"","reps":0,"bank":"modulowa"},{"id":"guzy-q5","at":"guzy","type":"mcq","mods":["13"],"topic":"Typy guzów i MRI","stem":"62-letnia kobieta z wieloletnim wywiadem łagodnych napadów ogniskowych przeszła MRI głowy: uwidoczniono dobrze odgraniczony guz zewnątrzmózgowy w okolicy przystrzałkowej, szeroko oparty na oponie twardej, wzmacniający się jednorodnie po kontraście z widocznym linijnym wzmocnieniem przylegającej opony („ogon oponowy”, dural tail) oraz hiperostozą kości czaszki. Jakie rozpoznanie jest najbardziej prawdopodobne?","opts":["Oponiak (meningioma)","Skąpodrzewiak (oligodendroglioma) z kodelecją 1p/19q","Pierwotny chłoniak OUN (PCNSL)","Przerzut czerniaka złośliwego","Wyściółczak (ependymoma) komory IV"],"keys":[0],"conf":"src","adapt":false,"gap":false,"src":"Sylabus PUM · Sem TK05 / Stępień, Podemski","why":"Oponiak jest najczęstszym pierwotnym łagodnym guzem wewnątrzczaszkowym u dorosłych (częstszy u kobiet ~2:1, często z receptorami progesteronowymi). Jest guzem zewnątrzmózgowym (uciska korę od zewnątrz, nie nacieka jej w stopniu WHO 1), silnie i jednorodnie wzmacnia się po gadolinie, daje charakterystyczny „ogon oponowy” (dural tail) i hiperostozę sąsiedniej kości.","tip":"Widzisz w opisie MRI słowa „zewnątrzmózgowy + jednorodne wzmocnienie + ogon oponowy (dural tail) + hiperostoza”? Szukaj w odpowiedziach oponiaka.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"guzy-q6","at":"guzy","type":"mcq","mods":["13"],"topic":"Guzy rdzenia i leczenie","stem":"U 52-letniej chorej z postępującym bólem korzeniowym na wysokości klatki piersiowej w MRI kręgosłupa piersiowego stwierdzono śródtwardówkowy zewnątrzrdzeniowy oponiak uciskający prawą połowę rdzenia na poziomie Th7. Jaki zespół objawów (Brown-Séquarda) wystąpi poniżej poziomu uszkodzenia?","opts":["Tożstronny (prawostronny) niedowład spastyczny i utrata czucia głębokiego oraz przeciwstronna (lewostronna) utrata czucia bólu i temperatury","Przeciwstronny (lewostronny) niedowład spastyczny oraz tożstronna (prawostronna) utrata czucia bólu i temperatury","Obustronne rozszczepienne zniesienie czucia bólu i temperatury wyłącznie w dermatomach Th7–Th8 przy pełnym zachowaniu siły kończyn dolnych","Wiotkie porażenie kończyn dolnych ze zniesieniem odruchów kolanowych i skokowych oraz znieczuleniem typu spodenek jeździeckich"],"keys":[0],"conf":"src","adapt":false,"gap":false,"src":"Sylabus PUM · Ćw TK09 / Fuller, Podemski","why":"Guzy śródtwardówkowe zewnątrzrdzeniowe (oponiaki, nerwiaki) uciskają rdzeń z boku, wywołując zespół połowiczego uszkodzenia rdzenia (Brown-Séquarda). Droga piramidowa i sznury tylne (czucie głębokie i wibracji) krzyżują się w pniu/opuszce (powyżej rdzenia piersiowego), więc ich objawy są TOŻSTRONNE do ucisku. Droga rdzeniowo-wzgórzowa boczna (ból i temperatura) krzyżuje się na poziomie rdzenia, dlatego jej ubytek występuje po stronie PRZECIWNEJ (1–2 segmenty poniżej).","tip":"Brown-Séquard w jednym zdaniu: siła i wibracja = po tej samej stronie co guz; ból i temperatura = po stronie przeciwnej.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"guzy-q7","at":"guzy","type":"mcq","mods":["13"],"topic":"Guzy rdzenia i leczenie","stem":"68-letni mężczyzna z rakiem płuca od 10 dni ma narastający w nocy ból kręgosłupa piersiowego, a od 6 godzin osłabienie obu kończyn dolnych i zatrzymanie moczu (podejrzenie przerzutowej kompresji zewnątrzoponowej rdzenia). Z kolei drugi pacjent na oddziale ma bezobjawowego w zakresie drgawek oponiaka płata czołowego przed planową resekcją. Które postępowanie jest PRAWIDŁOWE?","opts":["U chorego z rakiem płuca odczekać z podaniem deksametazonu do planowego MRI za 72 h; u pacjenta z oponiakiem bez napadów włączyć profilaktycznie fenytoinę","U chorego z podejrzeniem ucisku rdzenia natychmiast podać deksametazon i.v. i wykonać pilne MRI całego kręgosłupa (<24 h) oraz konsultację odbarczającą; u pacjenta z guzem bez napadów nie włączać rutynowo profilaktyki przeciwpadaczkowej","U chorego z kompresją rdzenia wykonać natychmiastową punkcję lędźwiową w odcinku lędźwiowym przed MRI","U chorego z kompresją rdzenia zastosować wyłącznie mannitol i unikać glikokortykosteroidów"],"keys":[1],"conf":"inf","adapt":false,"gap":true,"src":"Wytyczne EANO / SNO / NICE · Sylabus TK05","why":"Zewnątrzoponowa kompresja rdzenia (MESCC) to stan nagły neuroonkologiczny: ból nocny kręgosłupa wyprzedza deficyt ruchowy, a z chwilą pojawienia się niedowładu i zatrzymania moczu należy natychmiast podać deksametazon i.v. oraz wykonać pilne MRI całego kręgosłupa (przerzuty bywają wielopoziomowe) przed odbarczeniem/radioterapią. Natomiast u pacjentów z guzami mózgu bez napadów padaczkowych wytyczne SNO/EANO nie zalecają rutynowej profilaktyki pierwotnej lekami przeciwpadaczkowymi.","tip":"Dwie złote zasady terapii wspomagającej: (1) deksametazon natychmiast w obrzęku guzowym i kompresji rdzenia (wyjątek: podejrzenie chłoniaka OUN bez wgłobienia przed biopsją), (2) leki przeciwpadaczkowe dopiero po napadzie — preferowany lewetyracetam.","zal":"W części starszych schematów przed operacją guza mózgu rutynowo włączano profilaktycznie leki przeciwpadaczkowe (często fenytoinę lub karbamazepinę).","akt":"Aktualne wytyczne SNO i EANO odradzają rutynową profilaktykę przeciwpadaczkową u chorych z guzem OUN bez napadów. Jeśli napad wystąpi, lekiem z wyboru jest lewetyracetam (brak indukcji enzymów CYP450 i brak interakcji z chemioterapią/deksametazonem).","ans":"","reps":0,"bank":"modulowa"},{"id":"zwyr-q1","at":"zwyrodnienia","type":"mcq","mods":["14"],"topic":"Parkinson i atypowe","stem":"63-letni mężczyzna zgłasza stopniowo narastające od 8 miesięcy spowolnienie ruchowe prawej ręki, trudność z zapinaniem guzików, ściszenie mowy (hipofonia) oraz spoczynkowe drżenie palców prawej dłoni o charakterze „liczenia pieniędzy”, które zmniejsza się przy sięganiu po kubek. W badaniu stwierdzono bradykinezję i wzmożenie napięcia mięśniowego typu koła zębatego po stronie prawej, odruchy głębokie symetryczne, próba pociągnięcia prawidłowa. Który zestaw jest najbardziej charakterystyczny dla rozpoznania oraz leczenia I rzutu?","opts":["Drżenie spoczynkowe jest warunkiem koniecznym rozpoznania; lekiem z wyboru jest haloperidol w małej dawce","Warunkiem koniecznym rozpoznania jest bradykinezja z min. jednym objawem osiowym (sztywność typu koła zębatego lub drżenie spoczynkowe 4–6 Hz); podstawowym lekiem objawowym jest lewodopa z inhibitorem dekarboksylazy","Rozpoznanie wymaga wczesnych upadków do tyłu w 1. roku choroby oraz pionowego porażenia spojrzenia w dół","Podstawą leczenia przyczynowego jest ryluzol 2×50 mg oraz natychmiastowe odstawienie białek w diecie","Rozpoznanie stawia się wyłącznie po stwierdzeniu objawu Babińskiego i zaniku mięśni kłębu ręki"],"keys":[1],"conf":"src","adapt":false,"gap":true,"src":"Sylabus PUM W03d · Sem TK06 · Wskazówka #8 · Podemski","why":"Zgodnie z Wskazówką egzaminacyjną PUM #8 i kryteriami MDS chorobę Parkinsona rozpoznaje się na podstawie obecności bradykinezji (warunek konieczny!) oraz co najmniej jednego z objawów: sztywności mięśniowej („koło zębate” / „ołowiana rura”) lub drżenia spoczynkowego 4–6 Hz ustępującego przy ruchu celowym. Złotym standardem leczenia objawowego, dającym wyraźną poprawę (test z lewodopą), jest lewodopa z inhibitorem dekarboksylazy (benserazyd lub karbidopa), przyjmowana 30–60 min przed posiłkiem.","tip":"Wskazówka PUM #8: Bradykinezja to warunek konieczny PD; asymetryczny początek i wybitna poprawa po lewodopie różnicują idiopatyczną PD od parkinsonizmów atypowych.","zal":"W starszych materiałach dydaktycznych u młodszych chorych (<65 r.ż.) zalecano rutynowe opóźnianie włączenia lewodopy na rzecz agonistów dopaminy lub inhibitorów MAO-B, aby odwlec wystąpienie dyskinez.","akt":"Aktualne wytyczne MDS/EAN podkreślają, że nie należy wstrzymywać lewodopy u chorych z objawami upośledzającymi funkcjonowanie niezależnie od wieku — jest najskuteczniejsza, a ryzyko dyskinez zależy głównie od czasu trwania choroby i pulsacyjnej stymulacji, nie samego momentu startu L-dopy.","ans":"","reps":0,"bank":"modulowa"},{"id":"zwyr-q2","at":"zwyrodnienia","type":"mcq","mods":["14"],"topic":"Parkinson i atypowe","stem":"68-letnia kobieta od 10 miesięcy ma szybko postępujące zaburzenia równowagi z wielokrotnymi upadkami do tyłu, symetryczną sztywność osiową tułowia i szyi (retrocollis), niewyraźną mowę oraz brak poprawy po zwiększaniu dawki lewodopy do 1000 mg/dobę. W badaniu stwierdzono niemal całkowite zniesienie ruchów gałek ocznych w płaszczyźnie pionowej (zwłaszcza patrzenia w dół) i „zdziwiony” wyraz twarzy, a w MRI mózgu zanik nakrywki śródmózgowia (objaw kolibra). Najbardziej prawdopodobne rozpoznanie to:","opts":["Idiopatyczna choroba Parkinsona","Zanik wieloukładowy (MSA)","Postępujące porażenie nadjądrowe (PSP)","Zwyrodnienie korowo-podstawne (CBD)","Wodogłowie normotensyjne (NPH)"],"keys":[2],"conf":"src","adapt":false,"gap":false,"src":"Sylabus PUM W03d · Sem TK06 · Stępień · Kozubski","why":"Wczesne upadki do tyłu (<1. roku choroby), symetryczny parkinsonizm osiowy z retrocollis, porażenie pionowego spojrzenia (początkowo w dół), brak odpowiedzi na lewodopę oraz zanik śródmózgowia dający w strzałkowym MRI „objaw kolibra” to klasyczny obraz postępującego porażenia nadjądrowego (PSP — taupatia 4R). MSA cechuje wczesna ciężka dysautonomia (hipotonia ortostatyczna, nietrzymanie moczu) i „objaw krzyża w moście”, a CBD — skrajna asymetria ze zjawiskiem obcej ręki.","tip":"Szybkie skojarzenia Parkinson-plus: PSP = upadki do tyłu + spojrzenie w dół + koliber; MSA = ortostaza + zwieracze + krzyż w moście; CBD = asymetria + obca ręka.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"zwyr-q3","at":"zwyrodnienia","type":"mcq","mods":["14"],"topic":"SLA (UMN + LMN)","stem":"58-letni mężczyzna zgłasza postępujące od 7 miesięcy osłabienie i wyraźny zanik drobnych mięśni prawej ręki z widocznymi drżeniami pęczkowymi (fascykulacjami) przedramion oraz kurczami łydek, a ostatnio także niewyraźną mowę i trudności w połykaniu. W badaniu neurologicznym stwierdza się zanik mięśni międzykostnych i kłębu ręki, fascykulacje języka, a jednocześnie wygórowane odruchy głębokie w obu kończynach górnych i dolnych z obustronnym objawem Babińskiego. Czucie dotyku, bólu i wibracji oraz funkcja zwieraczy są całkowicie prawidłowe. Które rozpoznanie i lek modyfikujący przebieg choroby są właściwe?","opts":["Zespół Guillaina-Barrégo; dożylne immunoglobuliny (IVIG)","Stwardnienie zanikowe boczne (SLA); ryluzol 2×50 mg p.o.","Mielopatia szyjna ze zwyrodnienia kręgosłupa; wyłącznie lewodopa","Miastenia gravis (postać opuszkowa); pirydostygmina i tymektomia","Zwyrodnienie powrózkowe rdzenia kręgowego; witamina B12 i.m."],"keys":[1],"conf":"src","adapt":false,"gap":true,"src":"Sylabus PUM W03d · Wskazówka #9 · Podemski · Stępień","why":"Zgodnie z Wskazówką egzaminacyjną PUM #9 jednoczesne występowanie objawów uszkodzenia dolnego neuronu ruchowego (LMN: zaniki mięśni, fascykulacje na kończynach i języku) oraz górnego neuronu ruchowego (UMN: wygórowane odruchy z zanikłych mięśni, objaw Babińskiego) przy całkowitym zaoszczędzeniu czucia i funkcji zwieraczy jest patognomoniczne dla stwardnienia zanikowego bocznego (SLA). Jedynym klasycznym lekiem doustnym o udowodnionym wydłużeniu przeżycia jest ryluzol (antyglutaminergiczny), obok wczesnej wentylacji nieinwazyjnej (NIV).","tip":"Wskazówka PUM #9: SLA = UMN + LMN (zanik + fascykulacje + wygórowane odruchy/Babiński) BEZ zaburzeń czucia i zwieraczy. Zawsze wyklucz w MRI mielopatię szyjną!","zal":"Tradycyjnie w pytaniach testowych rozpoznanie SLA opiera się na kryteriach El Escorial (pewne, prawdopodobne, możliwe), a jedynym wymienianym lekiem jest ryluzol.","akt":"Współczesne wytyczne stosują uproszczone kryteria Gold Coast (UMN+LMN w ≥1 okolicy lub LMN w ≥2 okolicach po wykluczeniu mimików), rutynowo poszukują mutacji (zwłaszcza SOD1 i C9orf72) i dopuszczają terapię celowaną antysensowną (tofersen w SOD1-SLA) oraz edarawon; przeżycie najmocniej wydłuża wczesna NIV i gastrostomia (PEG).","ans":"","reps":0,"bank":"modulowa"},{"id":"zwyr-q4","at":"zwyrodnienia","type":"mcq","mods":["15"],"topic":"Otępienia (AD/FTD/VaD/DLB)","stem":"75-letnia kobieta została przywieziona przez rodzinę z powodu trwającego od 2 lat powolnego, jednostajnego pogarszania się pamięci — powtarza te same pytania po kilku minutach, zapomina niedawnych rozmów, gubi się w nowej okolicy i ma trudności z nazywaniem przedmiotów, natomiast pamięć wydarzeń z młodości jest początkowo zachowana. W badaniu przedmiotowym bez ogniskowego niedowładu, wynik MMSE 20/30 pkt; w MRI uogólniony zanik korowy z wyraźną przewagą w przyśrodkowych częściach płatów skroniowych (hipokampy). Jaki profil biomarkerów w płynie mózgowo-rdzeniowym i jakie leczenie I rzutu odpowiadają temu rozpoznaniu?","opts":["Podwyższone Aβ42 i obniżone białko tau w PMR; haloperidol i memantyna","Obniżone Aβ42 oraz podwyższone p-tau/t-tau w PMR; inhibitor acetylocholinoesterazy (np. donepezil lub rywastygmina)","Prawidłowy profil PMR; w chorobie Alzheimera leki cholinergiczne są przeciwwskazane","Obniżone białko tau i obecność prążków oligoklonalnych IgG; wysokie dawki metyloprednizolonu","Zwiększone stężenie białka 14-3-3 w PMR charakterystyczne dla otępienia naczyniopochodnego; tylko ASA"],"keys":[1],"conf":"src","adapt":false,"gap":true,"src":"Sylabus PUM W03f · Sem TK07 · Podemski · Stępień","why":"Podstępny, powoli postępujący ubytek pamięci epizodycznej (świeżej) z zanikiem przyśrodkowych płatów skroniowych (hipokampów) to typowa choroba Alzheimera (AD). Odkładanie β-amyloidu w płytkach starczych w mózgu powoduje obniżenie stężenia rozpuszczalnego peptydu Aβ42 w PMR (oraz stosunku Aβ42/40), natomiast zwyrodnienie neurofibrylarne uwalnia do PMR hiperfosforylowane tau (↑ p-tau) i całkowite tau (↑ t-tau). W otępieniu lekkim i umiarkowanym lekiem I rzutu są inhibitory acetylocholinoesterazy (donepezil, rywastygmina, galantamina), a w umiarkowanym/ciężkim dołącza się memantynę.","tip":"W chorobie Alzheimera w PMR spada Aβ42 (bo „uwięziony” w płytkach w korze!), a rośnie p-tau i t-tau (bo neurony ulegają rozpadowi).","zal":"Klasycznie w sylabusie i egzaminach wymienia się wyłącznie leczenie objawowe AD: inhibitory AChE (donepezil, rywastygmina, galantamina) oraz antagonistę NMDA (memantyna).","akt":"Aktualnie rozpoznanie AD opiera się na kryteriach biologicznych ATN (amyloid-tau-neurodegeneracja: PMR lub PET amyloid/tau), a w wytycznych pojawiły się pierwsze terapie modyfikujące przebieg wczesnej AD — przeciwciała anty-amyloidowe (lekanemab, donanemab), wymagające monitorowania MRI pod kątem powikłań ARIA.","ans":"","reps":0,"bank":"modulowa"},{"id":"zwyr-q5","at":"zwyrodnienia","type":"mcq","mods":["15"],"topic":"Otępienia (AD/FTD/VaD/DLB)","stem":"57-letni dotychczas zdrowy mężczyzna od roku stał się wulgarny, utracił empatię wobec bliskich, podejmuje ryzykowne decyzje finansowe, objada się słodyczami i powtarza stereotypowe gesty. Jednocześnie bez trudu przypomina sobie niedawne wydarzenia rodzinne, orientuje się w czasie i przestrzeni oraz uzyskuje 28/30 pkt w skali MMSE. W MRI głowy widoczny asymetryczny zanik płatów czołowych i przednich części płatów skroniowych. Które rozpoznanie i stwierdzenie terapeutyczne są prawdziwe?","opts":["Otępienie z ciałami Lewy’ego (DLB); wskazany haloperidol i.m.","Wariant behawioralny otępienia czołowo-skroniowego (bvFTD); inhibitory acetylocholinoesterazy (donepezil) nie przynoszą korzyści i mogą nasilać pobudzenie","Wczesna choroba Alzheimera; wynik MMSE 28/30 wyklucza proces neurozwyrodnieniowy","Otępienie naczyniopochodne (VaD); skala Hachińskiego wynosi zwykle <4 pkt","Depresja rzekomootępienna; konieczne natychmiastowe podanie rysperydonu"],"keys":[1],"conf":"inf","adapt":false,"gap":false,"src":"Sylabus PUM W03f · Sem TK07 · Kozubski · Stępień","why":"Wczesny wiek zachorowania (przed 65. r.ż.), wiodąca zmiana osobowości i zachowania społecznego (odhamowanie, utrata empatii, hiperoralność, stereotypie) przy względnym zachowaniu pamięci epizodycznej i orientacji wzrokowo-przestrzennej (oraz wysokim wyniku MMSE!) z zanikiem płatów czołowo-skroniowych w MRI to klasyczny wariant behawioralny FTD (bvFTD). W przeciwieństwie do AD i DLB w FTD nie występuje wiodący deficyt cholinergiczny, więc inhibitory AChE są nieskuteczne i mogą nasilać pobudzenie.","tip":"Prawidłowe MMSE (27–30 pkt) NIE wyklucza FTD ani wczesnego VaD — w bvFTD zawodzą funkcje wykonawcze i zachowanie społeczne, a nie pamięć świeża!","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"zwyr-q6","at":"zwyrodnienia","type":"mcq","mods":["15"],"topic":"Otępienia (AD/FTD/VaD/DLB)","stem":"76-letni chory z narastającymi od roku wahaniami sprawności poznawczej („raz rozmawia logicznie, po południu jest głęboko splątany”) opisuje szczegółowe, powtarzające się omamy wzrokowe (widzi obce dzieci w pokoju), od kilku miesięcy porusza się wolno i sztywno (łagodny parkinsonizm), a żona podaje wieloletnie „odgrywanie snów” z krzykami w nocy (RBD). W oddziale internistycznym z powodu niepokoju podano mu doraźnie haloperidol, po którym rozwinął ciężką sztywność uogólnioną, zaburzenia świadomości i gorączkę. Najbardziej prawdopodobna diagnoza podstawowa to:","opts":["Otępienie z ciałami Lewy’ego (DLB) powikłane ciężką reakcją nadwrażliwości na neuroleptyki","Otępienie czołowo-skroniowe (FTD) z niedoborem witaminy B12","Choroba Alzheimera o typowym, jednostajnym przebiegu","Otępienie wielozawałowe (VaD) po udarze móżdżku","Zespół rzekomootępienny w przebiegu niedoczynności tarczycy"],"keys":[0],"conf":"src","adapt":false,"gap":false,"src":"Sylabus PUM W03f · Sem TK07 · Stępień · Kozubski","why":"Triada: fluktuacje poznawcze i uwagi + wczesne żywe omamy wzrokowe + parkinsonizm (występujący równolegle lub ≤1 rok przed/po początku otępienia — „reguła 1 roku”) oraz zaburzenia zachowania w fazie snu REM (RBD) definiuje otępienie z ciałami Lewy’ego (DLB). Cechą kluczową klinicznie jest skrajna nadwrażliwość na klasyczne neuroleptyki (np. haloperidol) mogąca prowadzić do zagrażającego życiu zespołu neuroleptycznego lub nieodwracalnego pogorszenia sprawności.","tip":"W DLB i otępieniu w PD haloperidol jest ŚMIERTELNIE groźną pułapką! Na omamy i funkcje poznawcze stosuj rywastygminę/donepezil, a doraźnie tylko kwetiapinę lub klozapinę.","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"zwyr-q7","at":"zwyrodnienia","type":"mcq","mods":["15"],"topic":"Skale i odwracalne (NPH)","stem":"73-letni mężczyzna zgłasza się z powodu postępującego od 6 miesięcy zaburzenia chodu („nie może oderwać stóp od podłogi”, chodzi drobnymi krokami na szerokiej podstawie, tzw. chód magnetyczny), spowolnienia myślenia (MoCA 19/30) oraz naglących parć i nietrzymania moczu. Siła w nogach w badaniu na leżąco jest prawidłowa (5/5), brak zaników i objawu Babińskiego. W TK głowy poszerzenie układu komorowego przy wąskich bruzdach na sklepistości mózgu (wskaźnik Evansa 0,36). Które rozpoznanie i badanie potwierdzające wskazanie do leczenia przyczynowego są właściwe?","opts":["Choroba Alzheimera; oznaczenie stężenia amoniaku i włączenie donepezilu","Wodogłowie normotensyjne (NPH — triada Hakima); test upustowy PMR (30–50 ml) z oceną poprawy chodu i kwalifikacja do zastawki komorowo-otrzewnowej (VPS)","Zwyrodnienie korowo-podstawne (CBD); podanie wysokich dawek metyloprednizolonu","Stwardnienie zanikowe boczne; włączenie ryluzolu bez nakłucia lędźwiowego","Otępienie czołowo-skroniowe; terapia elektrokonwulsyjna"],"keys":[1],"conf":"did","adapt":false,"gap":false,"src":"Sylabus PUM W03f · Sem TK07 · Podemski · Stępień","why":"Klasyczna triada Hakima (zaburzenia chodu typu magnetycznego jako objaw najwcześniejszy + otępienie podkorowe + nietrzymanie moczu) ze wskaźnikiem Evansa >0,30 i zachowaną siłą mięśniową na leżąco wskazuje na wodogłowie normotensyjne (NPH) — jedną z najważniejszych potencjalnie odwracalnych przyczyn otępienia i zaburzeń chodu. Przejściowa obiektywna poprawa chodu po upuście 30–50 ml PMR (tap-test) potwierdza celowość implantacji zastawki komorowo-otrzewnowej (VPS).","tip":"W NPH kolejność objawów i szans na poprawę po zastawce to: najpierw i najlepiej reaguje CHÓD („mokry, chwiejny i otępiały” = wet, wobbly, wacky).","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"diag-q1","at":"diagnostyka","type":"mcq","mods":["16"],"topic":"TK, MRI i Doppler","stem":"66-letni mężczyzna z nagłą afazją i prawostronnym niedowładem kończyny górnej obudził się z objawami (ostatnio widziany zdrowy 7 godzin temu). TK głowy bez kontrastu wykluczyło krwotok i rozległą hipodensję. W pilnym MRI stwierdzono wyraźną restrykcję dyfuzji w lewym terytorium MCA (DWI jasne, ADC ciemne) przy braku zmian hiperintensywnych w sekwencji FLAIR. Co oznacza układ sygnałów DWI(+)/FLAIR(−)?","opts":["Przewlekły, dokonany zawał niedokrwienny sprzed kilku miesięcy z obecnością gliozy","Bardzo świeży zawał niedokrwienny (&lt;4,5 h od zachorowania) — stanowi przesłankę do rozważenia trombolizy dożylnej w protokole WAKE-UP","Krwotok śródmózgowy w fazie nadostrej wymagający natychmiastowego odwrócenia krzepnięcia","Odkładanie manganu w jądrach podstawy w przebiegu encefalopatii wątrobowej","Wykluczenie ostrego niedokrwienia i rozpoznanie przedłużonej aury migrenowej"],"keys":[1],"conf":"did","adapt":false,"gap":true,"src":"Sylabus PUM [16] · Wykład TK04 / U11 · MRI w ostrym udarze","why":"Ograniczenie dyfuzji (DWI jasne + mapa ADC ciemna) pojawia się już po kilkunastu minutach od zamknięcia naczynia (obrzęk cytotoksyczny), natomiast hiperintensywność w sekwencji FLAIR rozwija się dopiero po ok. 4,5 godziny. Niezgodność DWI(+)/FLAIR(−) wskazuje więc na bardzo wczesny udar mieszczący się w oknie trombolizy dożylnej.","tip":"DWI + ADC reagują w minutach; FLAIR potrzebuje ok. 4,5 h. Mismatch DWI(+)/FLAIR(−) otwiera drogę do rtPA przy nieznanym czasie zachorowania.","zal":"W klasycznym kryterium zegarowym (0–4,5 h od momentu ostatniego stanu bez objawów) pacjent z udarem po przebudzeniu o nieznanym czasie zachorowania był wykluczany z trombolizy dożylnej.","akt":"Aktualne wytyczne ESO (badania WAKE-UP i EXTEND) dopuszczają trombolizę i.v. przy nieznanym czasie zachorowania na podstawie „zegara tkankowego”: niezgodności DWI(+)/FLAIR(−) w MRI lub korzystnej penumbry w perfuzji TK/MRI.","ans":"","reps":0,"bank":"modulowa"},{"id":"diag-q2","at":"diagnostyka","type":"mcq","mods":["16"],"topic":"LP i profile PMR","stem":"42-letni mężczyzna trafił do SOR z gorączką 39,4°C, silnym bólem głowy, sztywnością karku oraz świeżo stwierdzonym niedowładem lewej kończyny górnej i sennością (GCS 11). Podejrzewasz ostre bakteryjne zapalenie opon mózgowo-rdzeniowych (ZOMR). Jaka jest prawidłowa kolejność działań diagnostyczno-terapeutycznych?","opts":["Natychmiastowe wykonanie nakłucia lędźwiowego bez wcześniejszego TK i podanie antybiotyku dopiero po uzyskaniu wyniku posiewu PMR","Pobranie posiewów krwi, natychmiastowe podanie empirycznego antybiotyku i.v. oraz deksametazonu PRZED wykonaniem TK głowy, następnie TK i — po wykluczeniu przeciwwskazań — nakłucie lędźwiowe","Wykonanie planowego MRI mózgu z gadolinem i wstrzymanie się z lekami do czasu wykluczenia ropnia","Odstąpienie od antybiotykoterapii w pierwszych 24 godzinach do momentu weryfikacji wirusowego ZOMR w PMR"],"keys":[1],"conf":"src","adapt":false,"gap":true,"src":"Sylabus PUM [16] · Wykład TK05 / U12 · Bezpieczne LP i ZOMR","why":"Deficyt ogniskowy oraz zaburzenia świadomości (GCS <12–13) są bezwzględnym wskazaniem do wykonania TK głowy przed nakłuciem lędźwiowym (ryzyko wklinowania przy obecności masy lub obrzęku). Nie wolno jednak z tego powodu opóźniać leczenia bakteryjnego ZOMR — po pobraniu krwi na posiew podaje się antybiotyk i.v. i deksametazon jeszcze przed wyjazdem na TK.","tip":"Przy wskazaniach do TK przed LP w podejrzeniu ropnego ZOMR obowiązuje zasada: posiewy krwi → antybiotyk + deksametazon → TK → LP.","zal":"W pytaniach akademickich akcentuje się konieczność wykluczenia wzmożonego ICP i zmian ogniskowych w TK przed wykonaniem nakłucia lędźwiowego.","akt":"Wytyczne ESCMID i IDSA podkreślają równolegle, że oczekiwanie na TK nigdy nie może opóźnić podania antybiotyku i steroidu — leczenie empiryczne należy włączyć natychmiast po pobraniu posiewów krwi, przed obrazowaniem.","ans":"","reps":0,"bank":"modulowa"},{"id":"diag-q3","at":"diagnostyka","type":"mcq","mods":["16"],"topic":"LP i profile PMR","stem":"U 34-letniego pacjenta 2 tygodnie po ostrej infekcji przewodu pokarmowego narasta od stóp ku górze symetryczny niedowład wiotki kończyn dolnych i górnych ze zniesieniem odruchów głębokich, bez gorączki. W badaniu PMR w 10. dobie choroby stwierdzono: płyn wodojasny, cytoza 2 komórki/µl, stężenie białka 195 mg/dl, glukoza prawidłowa (68% glikemii). Jak nazywa się ten profil PMR i na co wskazuje?","opts":["Rozszczepienie białkowo-komórkowe — charakterystyczne dla zespołu Guillaina-Barrégo (GBS)","Pleocytoza granulocytarna z hipoglikorachią — ropne bakteryjne ZOMR","Rozszczepienie komórkowo-białkowe — swoiste dla stwardnienia rozsianego","Błona włóknikowa (pajęczynka) — gruźlicze ZOMR","Ksantochromia — krwotok podpajęczynówkowy (SAH)"],"keys":[0],"conf":"inf","adapt":false,"gap":false,"src":"Sylabus PUM [16][10] · U12 · Profile PMR (GBS)","why":"Wyraźnie podwyższone stężenie białka (>45 mg/dl, często >100–200 mg/dl) przy prawidłowej liczbie komórek (<5/µl) to klasyczne rozszczepienie białkowo-komórkowe w zespole Guillaina-Barrégo (lub CIDP). Uwaga kliniczna: w pierwszych 3–7 dniach choroby stężenie białka w PMR bywa jeszcze prawidłowe i nie wyklucza GBS.","tip":"GBS w PMR = wysokie białko + prawidłowa cytoza (rozszczepienie białkowo-komórkowe). W 1. tygodniu białko może być jeszcze w normie!","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"diag-q4","at":"diagnostyka","type":"mcq","mods":["16"],"topic":"EEG i EMG/ENG","stem":"W badaniu elektroneurograficznym (ENG) u pacjenta z przewlekłą symetryczną polineuropatią „skarpetkowo-rękawiczkową” stwierdzono znaczne obniżenie amplitudy potencjałów ruchowych (CMAP) i czuciowych (SNAP) przy prawidłowej (lub minimalnie obniżonej) prędkości przewodzenia nerwowego (NCV) i prawidłowych latencjach dystalnych, a w EMG igłowym – fibrylacje i dodatnie fale ostre w mięśniach dystalnych. Jaki typ uszkodzenia opisuje ten wynik?","opts":["Uszkodzenie pierwotnie demielinizacyjne (typowe dla AIDP/CIDP)","Pierwotnie miopatyczne uszkodzenie włókien mięśniowych","Polineuropatia aksonalna (typowo np. w cukrzycy, alkoholizmie lub niedoborze B₁₂)","Zaburzenie transmisji presynaptycznej w złączu nerwowo-mięśniowym (LEMS)"],"keys":[2],"conf":"did","adapt":false,"gap":false,"src":"Sylabus PUM [16] · Wykład TK05 / U13 · Neurofizjologia ENG/EMG","why":"W uszkodzeniu aksonalnym spada liczba czynnych aksonów, co bezpośrednio obniża amplitudę potencjałów CMAP i SNAP, podczas gdy pozostałe sprawne włókna przewodzą impulsy z prawidłową lub niemal prawidłową prędkością (NCV). Odnerwienie objawia się w EMG spoczynkowymi fibrylacjami i dodatnimi falami ostrymi. W demielinizacji dominują zaś zwolnienie NCV, wydłużenie latencji i bloki przewodzenia.","tip":"Amplituda w dół + prawidłowa prędkość = aksonopatia (cukrzyca, alkohol). Prędkość w dół + wydłużone latencje / fali F = demielinizacja (GBS/CIDP).","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"diag-q5","at":"diagnostyka","type":"mcq","mods":["12"],"topic":"Interna i niedobory","stem":"Do SOR przywieziono wychudzonego 53-letniego mężczyznę z wywiadem przewlekłego alkoholizmu, splątanego, z oczopląsem poziomym, obustronnym niedowładem odwodzenia gałek ocznych (n. VI) i ciężką ataksją tułowia. Glikemia z palca wynosi 52 mg/dl. Które postępowanie jest bezwzględnym priorytetem terapeutycznym?","opts":["Podanie najpierw stężonej glukozy 40% i.v. oraz obserwacja przez 6 godzin przed ewentualnym podaniem witamin","Natychmiastowe podanie wysokich dawek witaminy B₁ (tiaminy) dożylnie PRZED podaniem glukozy (lub równolegle po rozpoczęciu wlewu tiaminy)","Podanie witaminy B₆ doustnie oraz wykonanie planowego EMG kończyn dolnych","Włączenie haloperidolu i mannitolu jako leczenia z wyboru psychozy Korsakowa"],"keys":[1],"conf":"src","adapt":false,"gap":true,"src":"Sylabus PUM [12] · Wykład TK04 / TK05 · Encefalopatia Wernickego","why":"Triada: zaburzenia świadomości, oftalmoplegia/oczopląs i ataksja chodu u chorego niedożywionego lub z alkoholizmem to obraz encefalopatii Wernickego z niedoboru tiaminy (B₁). Podanie samej glukozy zużywa resztki tiaminy jako kofaktora dehydrogenazy pirogronianowej, wywołując lub gwałtownie nasilając martwicę ciał suteczkowatych i wzgórza — dlatego tiaminę i.v. podaje się PRZED glukozą.","tip":"W każdym podejrzeniu alkoholizmu/niedożywienia z hipoglikemią lub zaburzeniami świadomości: najpierw witamina B₁ i.v., dopiero potem glukoza!","zal":"W starszych opracowaniach podręcznikowych podawano jako standard 100 mg tiaminy i.m. lub i.v. na dobę.","akt":"Aktualne wytyczne EFNS i NICE zalecają w podejrzeniu encefalopatii Wernickego wysokie dawki pozajelitowe: 200–500 mg tiaminy i.v. co 8 h przez 3–5 dni (doustne wchłanianie jest niewystarczające, a 100 mg często nie zapobiega zespołowi Korsakowa).","ans":"","reps":0,"bank":"modulowa"},{"id":"diag-q6","at":"diagnostyka","type":"mcq","mods":["12"],"topic":"Interna i niedobory","stem":"64-letnia wegetarianka od roku przyjmująca przewlekle inhibitory pompy protonowej zgłasza drętwienie stóp i niepewność chodu, szczególnie nasilone w ciemności i podczas mycia twarzy nad umywalką. W badaniu neurologicznym: zniesione czucie wibracji i ułożenia w palcach stóp, wygórowane odruchy kolanowe, obustronny objaw Babińskiego oraz wyraźne zachwianie i tendencja do upadku natychmiast po zamknięciu oczu (przy oczach otwartych stoi stabilnie). Które rozpoznanie i interpretacja próby Romberga są prawidłowe?","opts":["Zespół móżdżkowy (ataksja móżdżkowa) — dodatni objaw Romberga świadczy o uszkodzeniu robaka móżdżku","Zwyrodnienie powrózkowe rdzenia z niedoboru witaminy B₁₂ (uszkodzenie sznurów tylnych i bocznych) — dodatni objaw Romberga przy oczach zamkniętych świadczy o ataksji tylnosznurowej (czuciowej)","Stwardnienie zanikowe boczne (SLA) — izolowane uszkodzenie sznurów tylnych z zachowanym czuciem wibracji","Encefalopatia wątrobowa — dodatni objaw Romberga wywołany hiperamonemią","Zespół ogona końskiego — obustronny objaw Babińskiego wynika z ucisku korzeni L5–S1"],"keys":[1],"conf":"inf","adapt":false,"gap":false,"src":"Sylabus PUM [12] · Wskazówka PUM #10 · Niedobór B₁₂ i sznury tylne","why":"Zespół łączy uszkodzenie sznurów tylnych (zniesione czucie głębokie wibracji i ułożenia, dodatnia próba Romberga — chory kompensuje deficyt wzrokiem przy oczach otwartych i traci równowagę po ich zamknięciu) oraz sznurów bocznych (wygórowane odruchy kolanowe, obustronny objaw Babińskiego) — to klasyczne podostre złożone zwyrodnienie rdzenia z niedoboru wit. B₁₂. W zespole móżdżkowym chory chwieje się już przy oczach otwartych.","tip":"Wskazówka PUM #10: próba Romberga dodatnia (upadek po zamknięciu oczu) = sznury tylne / czucie głębokie (np. B₁₂). W uszkodzeniu móżdżku pacjent jest niestabilny już przy oczach otwartych!","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"},{"id":"diag-q7","at":"diagnostyka","type":"mcq","mods":["12"],"topic":"Interna i niedobory","stem":"61-letni chory z wieloletnią, źle kontrolowaną cukrzycą typu 2 zgłosił się z powodu nagłego dwojenia, opadnięcia lewej powieki oraz ustawienia lewej gałki ocznej na zewnątrz i ku dołowi. W badaniu stwierdzono zniesienie ruchów przywodzenia, unoszenia i obniżania lewego oka, natomiast obie źrenice były równe (3 mm) i żywo reagowały na światło. Która interpretacja jest właściwa?","opts":["Oszczędzenie źrenicy przemawia za niedokrwiennym (mikronaczyniowym) uszkodzeniem nerwu III w przebiegu cukrzycy (zawał środka pnia nerwu)","Zachowana reakcja źrenicy jest objawem alarmowym pękniętego tętniaka tętnicy łączącej tylnej (TComP) uciskającego nerw III od zewnątrz","Obraz odpowiada porażeniu nerwu IV (bloczkowego), w którym oko ucieka do dołu i do wewnątrz","Jest to klasyczny zespół Lamberta-Eatona poprzedzający wykrycie raka drobnokomórkowego płuca"],"keys":[0],"conf":"own","adapt":false,"gap":false,"src":"Sylabus PUM [12][6] · Neuropatie cukrzycowe i Wskazówka PUM #1","why":"Włókna przywspółczulne zwężające źrenicę biegną na obwodzie (powierzchownie) nerwu okoruchowego (n. III) i otrzymują dobre ukrwienie z naczyń opony miękkiej. Cukrzycowa mononeuropatia niedokrwienna dotyczy naczyń własnych wnętrza nerwu (vasa nervorum), oszczędzając powierzchowne włókna źreniczne. Odwrotnie, ucisk z zewnątrz (np. tętniak TComP) najpierw uszkadza włókna przywspółczulne — daje rozszerzoną, niereagującą źrenicę i wymaga pilnego angio-TK.","tip":"Nerw III w cukrzycy = oszczędzona źrenica (niedokrwienie środka pnia). Nerw III z szeroką źrenicą = pilnie wyklucz tętniaka TComP w angio-TK!","zal":"","akt":"","ans":"","reps":0,"bank":"modulowa"}];
